  VALUES ('CORE', 7, 'Preferences screen: category × channel matrix, locks, quiet hours, digest time', 'The preferences model ([NEO-135](https://linear.app/neosleep/issue/NEO-135/preferences-model-category-channel-locked-categories-quiet-hours)) has no UI yet.', '* Add a "Notifications" entry in the account menu that opens the preferences screen.
