WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 13, 'Patient appointment reminders by email: 24 h + 2 h before, daytime only', 'Patients get no reminder before an appointment, which leads to no-shows. Patients have no app login, so email is the only channel in v1.', '* The scheduler sends 2 reminder emails per appointment:
  * 24 h before;
  * 2 h before, only if that falls between 08:00 and 20:00 in the clinic''s time zone.
* Content: date, time, clinic name and address, and the doctor''s name. It carries no diagnosis or study type (PHI minimum), and includes the .ics file from [NEO-29](https://linear.app/neosleep/issue/NEO-29/attach-ics-calendar-file-add-to-calendar-links-to-booking-emails) when that ticket is done.
* The email is in the patient''s locale.
* Sent only with email consent ([NEO-146](https://linear.app/neosleep/issue/NEO-146/patient-contact-consent-per-channel-in-the-qr-consent-email-phonesms)).
* Rescheduling re-plans the reminders; cancelling removes them.
* Idempotent: one row per `(appointment, offset)`.
* SMS comes later (NEO-148).',
    '* Tests: 24 h and 2 h each sent once; the 2 h reminder is skipped at night; reschedule/cancel updates the plan; no consent means skipped and logged.
* A real email is received on dev.
* [NEO-28](https://linear.app/neosleep/issue/NEO-28/send-booking-confirmation-emails-to-hcp-and-patient) is updated with the split between it and this ticket.', 'backlog', 2, ARRAY['Feature', 'Calendar', 'Notifications']::text[],
    '[]'::jsonb, NULL, 'linear_import', 'CORE-13', 'linear',
    '2026-09-27T01:07:21.609Z'::timestamptz, '2026-09-27T01:07:21.609Z'::timestamptz, '2026-09-27T01:07:21.609Z'::timestamptz, NULL)
  ON CONFLICT DO NOTHING
  RETURNING id
)
