)
INSERT INTO platform.work_item_event (item_id, kind, to_status, body, actor, actor_kind, created_at)
SELECT id, 'created', 'needs_review', 'Imported from Linear CORE-25', 'linear', 'import', '2026-09-16T20:59:35.380Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 26, 'Attach .ics calendar file + "Add to calendar" links to booking emails', '### As a patient or doctor, I want the appointment email to drop the visit straight into my phone/computer calendar, so that I don''t have to type it in manually.

Free, no-OAuth v1 for device-calendar sync. Generate a standard iCalendar (.ics) `VEVENT` per appointment, keyed by a stable UID (e.g. `appointment-{appointment.id}@neosleepcare.com`); reuse the same UID with `METHOD:REQUEST` (update) or `METHOD:CANCEL` on reschedule/cancel so the recipient''s calendar app updates the existing entry instead of creating a duplicate. Pair with plain "Add to Google Calendar" / "Add to [Outlook.com](<http://Outlook.com>)" links (URL-based, no library needed). Location field: patient''s organization/clinic address (confirmed with Łukasz).

Depends on: [NEO-27](https://linear.app/neosleep/issue/NEO-27/design-new-appointment-entity-for-patientdoctor-visits-rbac) (entity must exist) and [NEO-28](https://linear.app/neosleep/issue/NEO-28/send-booking-confirmation-emails-to-hcp-and-patient) (attaches to that email).

Full enrichment: `docs/stories/calendar-scheduling-epic.md`

### Acceptance Criteria

- [ ] .ics file attached to booking/reschedule/cancel emails, valid per RFC 5545 (test by opening in Google Calendar, Apple Calendar, Outlook)
- [ ] Same appointment reschedule updates the existing device-calendar entry (same UID), doesn''t create a duplicate
- [ ] Cancel sends `METHOD:CANCEL` and removes the entry from the recipient''s calendar app
- [ ] "Add to calendar" links present for Google C…', NULL,
