    '2026-09-28T18:12:26.428Z'::timestamptz, '2026-09-28T18:12:26.428Z'::timestamptz, '2026-09-28T18:12:26.428Z'::timestamptz, NULL)
  ON CONFLICT DO NOTHING
  RETURNING id
