INSERT INTO platform.work_item_event (item_id, kind, to_status, body, actor, actor_kind, created_at)
SELECT id, 'created', 'backlog', 'Imported from Linear CORE-49', 'linear', 'import', '2026-09-28T18:12:26.428Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 50, 'Users accept terms and privacy policy at registration and each new version at next login', 'The terms and privacy policy are our contract with users (round 1, F3). Nothing records which version each user accepted, and nothing asks them again when a text changes.', '* Registration (invite, set password, Google first login) requires accepting the current terms and privacy policy.
* The acceptance is stored as a consent: purpose `terms` / `privacy_policy`, text version, time, IP/device.
* When a new version is published, the user must accept it at the next login before continuing (round 2, Q3). Until then the user only sees the acceptance screen.
* The texts are PL/EN/MX, written by /legal.
* Admins can see who accepted which version.',
    '* A new user can''t finish registration without accepting (e2e).
* Publishing a version blocks existing users until they accept, and they get in afterwards (e2e).
* Acceptances are listed per user.', 'backlog', 2, ARRAY['Privacy', 'Feature']::text[],
    '[]'::jsonb, NULL, 'linear_import', 'CORE-50', 'linear',
    '2026-09-28T18:12:29.327Z'::timestamptz, '2026-09-28T18:12:29.327Z'::timestamptz, '2026-09-28T18:12:29.327Z'::timestamptz, NULL)
  ON CONFLICT DO NOTHING
  RETURNING id
)
INSERT INTO platform.work_item_event (item_id, kind, to_status, body, actor, actor_kind, created_at)
SELECT id, 'created', 'backlog', 'Imported from Linear CORE-50', 'linear', 'import', '2026-09-28T18:12:29.327Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 51, 'Patient record: consent chips in the header + Consents tab with history and PDFs', 'Nobody can see which consents a patient has given, when, or on which text.', '* **Header chips**, one per purpose group: health data, contact (email/SMS/WhatsApp), partners, marketing, research, photos. States: given / withdrawn / missing / outdated version. The patient header layout follows [NEO-56](https://linear.app/neosleep/issue/NEO-56/pwa-record-header-with-breadcrumb-salesforceveeva-pattern-patient-date)/57.
* **Consents tab**:
  * a timeline of every consent event (given, withdrawn, corrected), with source (QR / paper scan / clinic), text version, who and when;
  * the signed PDF or scan opens inline.
* **Visibility**: doctor, admin and manager see it; rep/KAM/MSL don''t (round 1, D2), enforced in the API.
* **Staff actions**: only withdraw or correct, each needing a reason (the dialog comes from the withdrawal ticket).
* Copy in en/pl/mx.',
    '* A doctor sees chips and history for their patient.
* A rep gets 403 from the API and sees no tab (tests).
* Real before/after screenshots on desktop and phone are attached.', 'backlog', 2, ARRAY['Privacy', 'Feature']::text[],
    '[]'::jsonb, NULL, 'linear_import', 'CORE-51', 'linear',
    '2026-09-28T18:12:39.549Z'::timestamptz, '2026-09-28T18:12:39.549Z'::timestamptz, '2026-09-28T18:12:39.549Z'::timestamptz, NULL)
  ON CONFLICT DO NOTHING
  RETURNING id
)
INSERT INTO platform.work_item_event (item_id, kind, to_status, body, actor, actor_kind, created_at)
SELECT id, 'created', 'backlog', 'Imported from Linear CORE-51', 'linear', 'import', '2026-09-28T18:12:39.549Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 52, 'Consent withdrawal: email link, privacy page from QR, clinic — processing blocked, record retained', 'GDPR art. 7(3) requires that withdrawing consent is as easy as giving it. Today there is no way to withdraw.', 'Three routes (round 2, Q1):

* **Email link**: every patient email carries a signed, expiring link to a withdrawal page. Contact channels and marketing need one click. Health data needs a confirmation step that explains the consequence.
* **Privacy page from QR**: the patient opens it without logging in, using a one-time code sent to their email or phone, sees their consents and withdraws them.
* **Clinic**: staff record a withdrawal on the patient''s behalf, with a reason; it is audited.

Effect (round 1, C2):

* Further processing for that purpose is blocked: senders check it, the UI warns, partner sharing stops.
* Existing records are kept for the legal retention period (PL 20 years, MX 5 years, from the DPIA) and marked.

Each withdrawal also notifies the treating doctor through the notification engine.',
    '* All 3 routes work end to end.
* A withdrawn contact channel is never used (test).
* A health-data withdrawal blocks edits and exports to partners but keeps the record (test).
* Tokens expire and are single-use.', 'backlog', 2, ARRAY['Privacy', 'Feature']::text[],
    '[]'::jsonb, NULL, 'linear_import', 'CORE-52', 'linear',
    '2026-09-28T18:12:45.296Z'::timestamptz, '2026-09-28T18:12:45.296Z'::timestamptz, '2026-09-28T18:12:45.296Z'::timestamptz, NULL)
  ON CONFLICT DO NOTHING
  RETURNING id
)
INSERT INTO platform.work_item_event (item_id, kind, to_status, body, actor, actor_kind, created_at)
SELECT id, 'created', 'backlog', 'Imported from Linear CORE-52', 'linear', 'import', '2026-09-28T18:12:45.296Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 53, 'Paper consent: upload the signed scan as evidence', 'Some patients sign on paper in the clinic (round 1, B1). That consent has to exist in the system with its proof attached.', '* On the patient''s Consents tab: "Add signed paper consent" → upload a PDF or photo (stored in file_attachment, private bucket) → choose the text version that was printed → tick the purposes the patient ticked on paper.
* The consent row''s source is `paper_scan`, with evidence = the file, and records who uploaded it and when.
* This is not staff creating a consent on their own: the scan is the patient''s own signature (round 2, Q2). The upload is audited.
* Printable consent forms per version and locale come from the same text version, so paper and QR match.',
    '* A scan can be uploaded, opens from the timeline, and counts as a given consent (test).
* An upload without a file is rejected.
* The printed form is available in PL and MX.', 'backlog', 3, ARRAY['Privacy', 'Feature']::text[],
    '[]'::jsonb, NULL, 'linear_import', 'CORE-53', 'linear',
    '2026-09-28T18:13:00.243Z'::timestamptz, '2026-09-28T18:13:00.243Z'::timestamptz, '2026-09-28T18:13:00.243Z'::timestamptz, NULL)
  ON CONFLICT DO NOTHING
  RETURNING id
)
INSERT INTO platform.work_item_event (item_id, kind, to_status, body, actor, actor_kind, created_at)
SELECT id, 'created', 'backlog', 'Imported from Linear CORE-53', 'linear', 'import', '2026-09-28T18:13:00.243Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 54, 'New consent text version: re-consent at next contact, required before use if the purpose widens', 'Consent texts will change. We need to know who agreed to which version and when to ask again (round 1, B3/B4).', '* Publishing a new text version marks existing consents as `outdated_version`. They stay valid until withdrawn (round 1, B4).
* At the next contact (QR form, patient email link) the patient sees the new version to accept, showing only the changes.
* If the new version **widens** the purpose (flagged by /legal on publish), processing under the new scope needs the new consent first. Old-scope processing continues.
* Marketing consents are reviewed every 2 years: the patient gets a gentle re-confirm at the next contact.
* Admin screen: publish a version (text per locale, change note, the widens-purpose flag).',
    '* Publishing marks rows outdated (test).
* The next QR visit asks for the new version (e2e).
* A widened purpose is blocked until re-consent (test).
* Marketing older than 2 years is flagged.', 'backlog', 3, ARRAY['Privacy', 'Feature']::text[],
    '[]'::jsonb, NULL, 'linear_import', 'CORE-54', 'linear',
    '2026-09-28T18:13:09.023Z'::timestamptz, '2026-09-28T18:13:09.023Z'::timestamptz, '2026-09-28T18:13:09.023Z'::timestamptz, NULL)
  ON CONFLICT DO NOTHING
  RETURNING id
)
INSERT INTO platform.work_item_event (item_id, kind, to_status, body, actor, actor_kind, created_at)
SELECT id, 'created', 'backlog', 'Imported from Linear CORE-54', 'linear', 'import', '2026-09-28T18:13:09.023Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 55, 'Missing consents: admin list + warning before any action that needs consent', 'Staff can''t see which patients lack a required consent. Actions that need consent (sending email, sharing with a partner, taking photos) are not guarded.', '* An admin/manager list of patients with a missing, withdrawn or outdated consent per purpose, filterable by purpose and territory, with a "send QR / email to consent" action.
* A central `requireConsent(patient, purpose)` check in the API for every consent-gated action: OrthoApnea order sharing, patient emails, photo upload, research export.
* In the UI, a soft inline warning before the action ("No consent for X — the patient must consent first"), following the [NEO-105](https://linear.app/neosleep/issue/NEO-105/one-inline-alert-for-the-whole-app-soft-card-patient-form-validation) style. The action is blocked in the API regardless.',
    '* The list shows the correct patients per purpose and is territory-scoped (test).
* Every gated action fails without consent in the API (tests).
* The warning appears in the UI with screenshots.', 'backlog', 3, ARRAY['Privacy', 'Feature']::text[],
    '[]'::jsonb, NULL, 'linear_import', 'CORE-55', 'linear',
    '2026-09-28T18:13:13.341Z'::timestamptz, '2026-09-28T18:13:13.341Z'::timestamptz, '2026-09-28T18:13:13.341Z'::timestamptz, NULL)
  ON CONFLICT DO NOTHING
  RETURNING id
)
INSERT INTO platform.work_item_event (item_id, kind, to_status, body, actor, actor_kind, created_at)
SELECT id, 'created', 'backlog', 'Imported from Linear CORE-55', 'linear', 'import', '2026-09-28T18:13:13.341Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 56, 'Patient data export: one button, readable PDF + machine JSON (GDPR art. 15 / ARCO access)', 'A patient may ask for all of their data (GDPR art. 15, and ARCO "Acceso" in MX). Today that would be manual work with no audit.', '* An admin clicks one button on the patient record and gets a ZIP containing:
  * a readable PDF (identity, consents with history, appointments, studies, questionnaires, documents list, orders, who accessed the record from audit_log);
  * a JSON of the same;
  * the original signed files.
* The export itself is audited (who, when, why: linked request id).
* The content is in the patient''s language.
* The output goes to the admin only. Delivery to the patient is manual or through the request register.',
    '* The export contains every entity type linked to the patient (test with a fixture patient).
* The PDF renders in PL/MX/EN.
* Only admin can export (403 test).
* The export is written to audit_log.', 'backlog', 3, ARRAY['Privacy', 'Feature']::text[],
    '[]'::jsonb, NULL, 'linear_import', 'CORE-56', 'linear',
    '2026-09-28T18:13:18.194Z'::timestamptz, '2026-09-28T18:13:18.194Z'::timestamptz, '2026-09-28T18:13:18.194Z'::timestamptz, NULL)
  ON CONFLICT DO NOTHING
  RETURNING id
)
INSERT INTO platform.work_item_event (item_id, kind, to_status, body, actor, actor_kind, created_at)
SELECT id, 'created', 'backlog', 'Imported from Linear CORE-56', 'linear', 'import', '2026-09-28T18:13:18.194Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 57, 'Data-subject request register: access, rectification, objection, erasure — with legal deadlines', 'GDPR and ARCO requests have legal deadlines. Nothing tracks when a request came in, who handles it, or whether it was answered in time.', '* A register (admin): request type (access, rectification, cancellation/erasure, objection, withdrawal), requester and patient/user, received_at, channel, assignee, status, answer, and attached files.
* The deadline is computed per jurisdiction: PL 1 month (GDPR art. 12), MX 20 business days (LFPDPPP). An extension is possible with a reason.
* Reminders go out through the notification engine ([CORE-3](https://linear.app/neosleep/issue/CORE-3/scheduler-delivery-worker-cloud-scheduler-tick-escalation-retention) scheduler) at 50%, 80% and the due date, to the assignee and admin.
* Actions link to the tools: export (access), patient edit (rectification), consent withdrawal, and legal retention (erasure is refused where retention applies, with a template reason).',
    '* A request computes the right deadline for PL and MX (tests incl. MX business days).
* Reminders fire once each.
* Every status change is audited.', 'backlog', 3, ARRAY['Privacy', 'Feature']::text[],
    '[]'::jsonb, NULL, 'linear_import', 'CORE-57', 'linear',
    '2026-09-28T18:13:23.194Z'::timestamptz, '2026-09-28T18:13:23.194Z'::timestamptz, '2026-09-28T18:13:23.194Z'::timestamptz, NULL)
