    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 59, '[AJM] Personal pitch links with the prospect''s logo in the AJ sketch', 'Alfred sends the same portfolio link to every prospect. Łukasz wants each prospect to get their own link that greets them and shows their brand next to AJ (decision X1 = "+ their logo in the monogram", 2026-09-29).', '* `?para=<slug>` link per prospect (e.g. [alfredjan.com/corporativo?para=bbva](<http://alfredjan.com/corporativo?para=bbva>))
* The pen writes "Hola <Name>" in the entry, and the hero greets them by name
* The AJ blueprint draws their logo beside ours before the lockup: "AJ × <Brand>"
