SELECT id, 'created', 'done', 'Imported from Linear CORE-94', 'linear', 'import', '2026-10-03T14:25:46.941Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 95, '@neo/device-order: shared zod rules (front + API), provider adapter, OA replica for tests', 'Order validation lives only in the wizard component (steps 3–4 have none), and the API passes the body to OA unchecked, in OA''s own field names. Tests stub fetch one test at a time, with no faithful copy of OA.', '* New package `@neo/device-order`: a canonical order model in our own names, plus zod 4 rules. Every rule mirrors an OA rule and cites its source. Includes `RULES_VERSION`.
* The PWA validates each step and the API validates again before any call to OA. A 400 response carries issues as {path, code}, and each code is an i18n key (en/pl/mx).
* `DeviceOrderProvider` interface: today''s OA integration becomes one adapter (`toOaPayload` runs on the server), and the view knows no OA field names.
* OA replica in `apps/api/test/oa-replica`: a stateful fake HTTP server built from recorded fixtures. Any call from a test to [apneadock.es](<http://apneadock.es>) fails.
* A DB advisory lock so a double submit creates exactly one order.',
    '- [ ] The same table of rule cases passes in both the PWA and the API
- [ ] An invalid body never reaches the replica (route test)
- [ ] Concurrent submits produce one OA order (test)
- [ ] The wizard contains no OA field names', 'needs_review', 2, '{}'::text[],
    '[{"kind":"artifact","url":"https://claude.ai/artifact/KpYsrf4PLjsKah86SWhFye","title":"Artifact: CORE-95 Decyzje D1–D3 w zamówieniu"},{"kind":"artifact","url":"https://claude.ai/artifact/1BqNaWYbGyPvG1fpbfaBSC","title":"Artifact: NEO-210 Zamówienia OA na wspólnych regułach"}]'::jsonb, NULL, 'linear_import', 'CORE-95', 'linear',
    '2026-10-03T14:35:37.276Z'::timestamptz, '2026-10-03T14:35:37.276Z'::timestamptz, '2026-10-03T14:35:37.276Z'::timestamptz, NULL)
