INSERT INTO platform.work_item_event (item_id, kind, to_status, body, actor, actor_kind, created_at)
SELECT id, 'created', 'done', 'Imported from Linear CORE-97', 'linear', 'import', '2026-10-03T17:25:48.456Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 98, 'CI: no red "cancelled" twin run on PRs (push + pull_request on the same commit)', 'Every push to a work branch that has an open PR starts two CI runs on the same commit, one from `push` and one from `pull_request`. The shared concurrency group cancels one of them, and GitHub shows that cancelled run as a red ✗ "test" on the PR ([lukasz512/NeoSleep#357](https://linear.app/neosleep/review/neo-209-resources-per-user-webinar-watch-status-resume-prompt-status-e1562d368052), [lukasz512/NeoSleep#360](https://linear.app/neosleep/review/neo-214-resources-hide-order-watchpat-webinars-colocacion-de-dam-one-11c12747ee9c)), even though the real run passed.', '* `ci.yml`: on `pull_request`, skip the jobs for heads that the push trigger already covers (`worktree-*`, `worker/*`, `claude/*`)
* `ci.yml`: concurrency grouped per event + branch, so a newer push cancels only an older push of the same branch
* `ci-status.mjs`: a commit is green only if no run on it failed, rather than whichever run is newest',
    '- [ ] ci-status tests cover a skipped PR twin and a failed push run
- [ ] The next push to an open PR shows no red cancelled check
- [ ] Renovate PRs still get CI', 'needs_review', 2, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/361","title":"CORE-98 CI: one run per commit, no red cancelled twin on PRs"},{"kind":"artifact","url":"https://claude.ai/artifact/XkCoKxfZikiTecR1C3C8Q8","title":"Artifact: CORE-98 No red cancelled CI twin"}]'::jsonb, NULL, 'linear_import', 'CORE-98', 'linear',
    '2026-10-03T17:36:47.937Z'::timestamptz, '2026-10-03T17:36:47.937Z'::timestamptz, '2026-10-03T17:36:47.937Z'::timestamptz, NULL)
  ON CONFLICT DO NOTHING
  RETURNING id
)
