SELECT id, 'created', 'done', 'Imported from Linear CORE-99', 'linear', 'import', '2026-10-03T17:42:40.964Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 103, 'Cut Claude session cost: lean startup context, cheaper subagents, context guard', 'Claude usage is high: 94% runs at >150k context and 78% comes from subagent sessions. Each session loads \~15-20k fixed tokens, and the per-prompt hooks add \~650 tokens to every prompt.', '* D1: one merged UserPromptSubmit hook, full rules on prompt 1, a 1-line reminder every 10th prompt
* D2: CLAUDE.md to \~8 KB, closed "PR Pending" memories to memory/archive/
* D3: subagents default to Sonnet, Explore on Haiku
* D4: disable unused marketing/engineering plugins in this project + a monthly /skill-doctor budget report
* D5: a context guard suggests /compact at \~120k and writes a handoff file
* cleanupPeriodDays=30; locked worktrees and fresh transcripts are never touched',
    '- [ ] hook tests pass (prompt 1 = full rules, 2-9 = nothing, 10 = reminder; guard fires once above threshold)
- [ ] CLAUDE.md ≤ 9 KB, MEMORY.md has only active entries
- [ ] a new session starts clean; the Artifact shows before/after tokens', 'done', 2, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/366","title":"CORE-103 Lean session context, context guard, cheaper subagents"},{"kind":"artifact","url":"https://claude.ai/artifact/PjAa3mbtCWzSchWW2Bzyfz","title":"Artifact: CORE-103 Session Cost"}]'::jsonb, NULL, 'linear_import', 'CORE-103', 'linear',
    '2026-10-03T20:03:46.990Z'::timestamptz, '2026-10-03T20:25:16.487Z'::timestamptz, '2026-10-03T20:25:16.487Z'::timestamptz, '2026-10-03T20:25:16.487Z'::timestamptz)
