UNION ALL SELECT id, 'comment', NULL, 'Every Claude session in NeoSleep now loads less fixed context and stops re-sending the same 2.5 KB of rules with each prompt. Long sessions get a nudge to /compact or /clear with a handoff file, and subagents default to the cheaper Sonnet.
