WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 114, 'User avatar: role badge (admin star, doctor specialty, manager, rep, KAM/MSL)', 'The signed-in user''s avatar (app bar, account menu) and user avatars in Users list/detail/mentions show only initials — the role is invisible. Doctors in the HCP list already carry a specialty badge ([NEO-57](https://linear.app/neosleep/issue/NEO-57/pwa-lists-shared-clinical-card-table-mobile-card-style)); users don''t.', 'Decisions (decision form user-avatar-role-badge-r1, [https://claude.ai/artifact/CSUouoJqHsPqU8R8Xq6Kfm](<https://claude.ai/artifact/CSUouoJqHsPqU8R8Xq6Kfm>)):

* doctor → specialty icon (stethoscope fallback), dark disc
* admin → star on a tenant-primary disc
* manager → shield-check, dark disc
* rep → map-pin, light outline disc (quietest)
