  VALUES ('CORE', 124, 'Security: sendPushToUser() reads push_subscription without tenant scoping', 'Found during [CORE-69](https://linear.app/neosleep/issue/CORE-69/security-push-subscription-routes-have-no-requireauth-withtenant): sendPushToUser() in apps/api/src/routes/push.ts reads subscriptions via the plain getDb() pool instead of withTenant, so it does not run inside the caller''s tenant schema — the same tenant-scoping bug [CORE-69](https://linear.app/neosleep/issue/CORE-69/security-push-subscription-routes-have-no-requireauth-withtenant) fixed on the routes.', '* Run sendPushToUser() inside the tenant context (withTenant / TenantContext) of the notification it sends
