     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 126, 'Harness e2e port per worktree, so parallel sessions don''t block each other''s pre-push', 'playwright.harness.config.ts always starts vite on port 5199 with strictPort and no server reuse. When two worktree sessions push at the same time, the second pre-push fails with "5199 is already used" ([NEO-228](https://linear.app/neosleep/issue/NEO-228/clinico-block-redesign-on-the-patient-form-cpap-devicepressure-after) was blocked 3× on 2026-10-04 by [NEO-236](https://linear.app/neosleep/issue/NEO-236/pwa-palette-more-contrast-less-medical-green-2-proposals) and qr-loader).', '* The port comes from the worktree path (a stable hash → 5200–5999). HARNESS_PORT overrides it.
* One worktree always gets the same port, so it still never reuses another worktree''s server.',
    '* Two worktrees get different harness ports.
* Pre-push e2e runs while another worktree''s harness server is up.', 'needs_review', 0, '{}'::text[],
    '[]'::jsonb, NULL, 'linear_import', 'CORE-126', 'linear',
    '2026-10-04T13:13:29.821Z'::timestamptz, '2026-10-04T13:13:29.821Z'::timestamptz, '2026-10-04T13:13:29.821Z'::timestamptz, NULL)
