INSERT INTO platform.work_item_event (item_id, kind, to_status, body, actor, actor_kind, created_at)
SELECT id, 'created', 'backlog', 'Imported from Linear CORE-127', 'linear', 'import', '2026-10-04T13:28:19.109Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 128, 'Stop Claude sessions exhausting the GitHub API limit', 'Parallel Claude sessions hit GitHub''s API rate limit (5000/h per user, plus a secondary limit), so CI status can''t be read and PR links are blocked. The main cause is that the quality-gate hook tells every session to run `gh run watch`, which polls every 3 s (\~40 calls/min per session). On top of that, `ci-status.mjs` calls the API on every Stop. A paid plan won''t fix this: Pro/Team keep the same 5000/h per-user limit.', '* A `ci-wait.mjs` script polls one run with a single `gh run view --json status,conclusion` per minute and backs off on 403/429. The hook recommends it instead of `gh run watch`.
* `ci-status.mjs` gets a cache shared by all worktrees (`.claude/local`): a finished run is cached for good per sha, a pending one for 60 s.
* A rate-limited response becomes the state `rate_limited`, which the hook shows as a warning (with the reset time) instead of blocking the session.
* ship-artifact''s `gh pr list` gets a 10-minute cache per branch.',
    '* Tests: a cache hit makes no gh call; a pending result expires after 60 s; a 403 rate-limit response is reported as `rate_limited`; ci-wait polls at most once a minute.
* The hook text no longer mentions `gh run watch`.', 'done', 2, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/408","title":"CORE-128 Share GitHub API answers across sessions; replace gh run watch"},{"kind":"artifact","url":"https://claude.ai/artifact/6fcjnZr9buS8XmJsERKNXJ","title":"Artifact: CORE-128 GitHub API Limit"}]'::jsonb, NULL, 'linear_import', 'CORE-128', 'linear',
    '2026-10-04T13:53:27.058Z'::timestamptz, '2026-10-04T15:53:09.038Z'::timestamptz, '2026-10-04T15:53:09.038Z'::timestamptz, '2026-10-04T15:53:09.038Z'::timestamptz)
  ON CONFLICT DO NOTHING
  RETURNING id
)
