SELECT id, 'created', 'done', 'Imported from Linear CORE-131', 'linear', 'import', '2026-10-04T16:17:00.884Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 132, 'Patient care team: booking with a non-assigned HCP assigns them to the patient', 'A patient has exactly one doctor (`patient.practitioner_id`). When a visit is booked with another HCP (e.g. an ENT or dentist), that HCP can''t see the patient afterwards, because the doctor access policy ([CORE-104](https://linear.app/neosleep/issue/CORE-104/doctor-sees-only-own-patients-row-level-access-policy-for-all-entities), `entityAccess.ts`) only checks that single column.', '* New tenant table `patient_practitioner` (FHIR CareTeam): patient ↔ many practitioners, with source (appointment / manual / former_primary), added_by, added_at. `patient.practitioner_id` stays the primary doctor (not duplicated in the table).
* `CreateAppointmentCommand`: if the chosen practitioner isn''t on the patient''s care team, add them after the booker confirms (`grant_access`, D4), same transaction, audit_log entry. Cancel/delete of their only visit with nothing recorded takes access back (D2). Admin/manager add+remove, reps only add (D3); only admin replaces the primary, who stays on the team (D5).
* Access policy: a doctor sees a patient when they are on the care team (list scope, `assertCanSeePatient`, `patientScopeCondition`).
* PWA patient card: list of assigned HCPs with their specialty.',
    '* Booking a visit with an unassigned HCP adds them; that HCP sees the patient in /patients and can open it; other doctors still get 404.
* Patient card shows all HCPs with specialties.
* Integration tests on a real DB cover the above.', 'done', 2, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/418","title":"CORE-132 Patient care team: booking with an unassigned HCP gives them access"},{"kind":"artifact","url":"https://claude.ai/artifact/JHJZHogkvDpbu9tTgcXs6U","title":"Artifact: CORE-132 Patient Care Team"}]'::jsonb, NULL, 'linear_import', 'CORE-132', 'linear',
    '2026-10-04T17:34:53.733Z'::timestamptz, '2026-10-04T18:29:46.950Z'::timestamptz, '2026-10-04T18:29:46.950Z'::timestamptz, '2026-10-04T18:29:46.950Z'::timestamptz)
  ON CONFLICT DO NOTHING
  RETURNING id
)
