     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 138, 'Booking dialog: API "grant_access required" shows the confirmation, not a generic error', 'On pwa-dev Łukasz booked a visit with a doctor outside the patient''s care team ([CORE-132](https://linear.app/neosleep/issue/CORE-132/patient-care-team-booking-with-a-non-assigned-hcp-assigns-them-to-the)) and got "No se pudo guardar la cita". His tab had not shown the access confirmation (stale bundle, or the care-team request failed), so the API''s 400 `grant_access` had no field in the form and fell back to the generic error.', 'When the API answers that `grant_access` is required, the booking dialog shows the notice + confirmation checkbox, marked as required, instead of the generic error. Changing the doctor resets it.',
    '* Dialog test: a 400 naming `grant_access` without the checkbox shown reveals the checkbox with the error, and a retry with it ticked sends `grant_access: true`.
* Verified on pwa-dev.', 'done', 2, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/431","title":"Worktree core 138 grant access error"},{"kind":"artifact","url":"https://claude.ai/artifact/QWKt78SXhFSgQoKU45Eehq","title":"Artifact: CORE-138 Booking Access Confirmation"}]'::jsonb, NULL, 'linear_import', 'CORE-138', 'linear',
