SELECT id, 'created', 'done', 'Imported from Linear CORE-138', 'linear', 'import', '2026-10-04T18:41:19.047Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 139, 'Calendar misses appointments booked in a clinic time zone behind the viewer''s', 'Appointments booked from the patient card show on the card but some never appear in Calendario. The calendar fetches `/api/v1/calendar` for the viewer''s device-local day/week/month, but draws each appointment on its wall-clock day in the clinic zone ([CORE-120](https://linear.app/neosleep/issue/CORE-120/booking-flow-refactor-appointments-shift-8-h-1500-shows-as-0700)). For an MX clinic seen from Poland (8 h behind), every appointment after \~16:00 MX falls into the next device day''s fetch, yet is drawn on the previous day, so no view ever shows it (day view: all MX evenings; week/month: the last day''s evening).', 'Pad the fetch window by 2 days each side (covers any zone pair) and keep only entries whose wall-clock day is inside the visible days (grid, list and filter counts).',
    '* Unit test: an MX 18:00 appointment, viewer in Europe/Warsaw, is shown in day and week views of its MX day.
* Filter counts only count visible-day entries.
* Verified on pwa-dev after merge.', 'done', 2, ARRAY['Bug']::text[],
    '[{"kind":"artifact","url":"https://claude.ai/artifact/3JhQqeQ9N3p48xgFwB3Mcq","title":"CORE-139 Artifact"},{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/432","title":"CORE-139 Calendar shows clinic-zone appointments missed by device-day fetches"}]'::jsonb, NULL, 'linear_import', 'CORE-139', 'linear',
    '2026-10-04T20:45:07.639Z'::timestamptz, '2026-10-04T21:11:22.080Z'::timestamptz, '2026-10-04T21:11:22.080Z'::timestamptz, '2026-10-04T21:11:22.080Z'::timestamptz)
  ON CONFLICT DO NOTHING
  RETURNING id
)
