    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 144, 'Deploy only the app that changed; stop duplicate CI on the promote PR', 'Every merge to dev/prod redeploys both the app and the site, even when only the API or docs changed. The dev→prod promote PR also re-runs CI on the commit the dev push already tested.', 'Path filters + per-branch concurrency group on deploy-pwa and deploy-web (a newer merge replaces a waiting deploy; a running FTP upload is never cancelled). CI skips the promote PR (head `dev`). The quality-gate devVerified hint mentions the path filters.',
    'An API-only merge to dev starts no Deploy App/Site run, an app change still deploys the app, and promote PR #436 stays green.', 'done', 0, '{}'::text[],
