WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 146, 'Drop legacy request_log table and audit_log session FK (migration 054)', '`request_log` is empty in every tenant schema and nothing writes to it any more (request context now lives on `audit_log`, PR [lukasz512/NeoSleep#441](https://linear.app/neosleep/review/core-pending-audit-log-fill-request-context-request-id-ip-ua-country-7c7e88c6d883)). `audit_log_session_id_fkey` ties audit rows to a session table we don''t need and blocks cleanup. Both are dead weight in schema, docs and skills.', '* `apps/api/migrations/054_drop_request_log.sql`: per tenant, drop `request_log` only when it is empty (NOTICE otherwise); drop `audit_log_session_id_fkey` but keep the `session_id` column; regenerate `create_tenant_schema()`.
* Test in `test/device-orders/oa-coverage-gaps.spec.ts` asserts the table is gone.
* Remove `request_log` from CLAUDE.md, the dba/arch skills and `_contracts/arch→legal.md`.',
    '* Migration 054 runs clean on a fresh postgres:15 and on dev; schema parity OK.
* API suite green; no code or docs reference `request_log`.
* `audit_log.session_id` still populated, no FK.', 'done', 0, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/456","title":"CORE-146 Drop legacy request_log and audit_log session FK (migration 054)"},{"kind":"artifact","url":"https://claude.ai/artifact/7vn9KQtKhZM8ZNEbFYESSh","title":"Artifact: CORE-146 Drop request_log"}]'::jsonb, NULL, 'linear_import', 'CORE-146', 'linear',
