WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 147, 'Trackable problem reports: receipt, My reports, ticket + reply', 'A doctor''s test report left no trace for the reporter: no confirmation, no notification, no way to see status or the ticket it was filed under. The Resources error state still used a mailto: "Report incident" that silently fails when the mail client isn''t used.', 'On top of [CORE-141](https://linear.app/neosleep/issue/CORE-141/pwa-medico) (platform.problem_report, #number): reporter gets in-app + email receipt with the number; tenant admins get an in-app heads-up; "My reports" (/my-reports, account menu) with status, manual ticket ID (format ABC-123) and admin reply; resolved / won''t fix → in-app + email with ticket + PHI-free reply; unsent draft kept on device 7 days; mailto: removed (Resources error opens the same dialog). Story: docs/stories/trackable-feedback-reports.md.',
    'A doctor''s report on pwa-dev shows in their notifications + inbox with its #number, reaches Łukasz, and the resolution email carries the CORE-n.', 'done', 0, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/453","title":"CORE-147 Trackable feedback reports: receipt, My reports, ticket + reply"},{"kind":"artifact","url":"https://claude.ai/artifact/6349CY2dybaUFPnj3qJz7e","title":"Artifact: CORE-147 Trackable Feedback Reports"}]'::jsonb, NULL, 'linear_import', 'CORE-147', 'linear',
    '2026-10-05T21:32:06.922Z'::timestamptz, '2026-10-05T22:08:40.824Z'::timestamptz, '2026-10-05T22:08:40.824Z'::timestamptz, '2026-10-05T22:08:40.824Z'::timestamptz)
