    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 149, 'List queue chips paint with the page, not after the counts request', 'On the doctor''s Estudios and Tratamientos lists, the queue chips (Needs you / In progress / Finished…) only appear once the separate `/queues` counts request returns. During the first load the skeleton shows without them, then they pop in and push the list down. Over an empty list they flash and disappear.', '`AppEntityList` renders the chips from the first frame (their labels are static). Until the counts arrive each count is a 20 px breathing placeholder (same size as "0", same breathe as the skeleton rows); the numbers fade in when they land. The chips also stay over the empty state, showing zeros. Reduced motion turns off both animations.',
    '* Chips are visible with the skeleton before any count has arrived (test)
* Chips stay over an empty list with 0 counts (test)
* No layout jump between skeleton → list on both lists, desktop and phone (before/after shots)', 'done', 0, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/457","title":"CORE-149 List queue chips paint with the skeleton, not after the counts"},{"kind":"artifact","url":"https://claude.ai/artifact/U1H3DXuFRdYBtRkyndsCSG","title":"Artifact: CORE-149 Queue chips load with the page"}]'::jsonb, NULL, 'linear_import', 'CORE-149', 'linear',
    '2026-10-05T22:03:23.013Z'::timestamptz, '2026-10-05T22:40:03.499Z'::timestamptz, '2026-10-05T22:40:03.499Z'::timestamptz, '2026-10-05T22:40:03.499Z'::timestamptz)
