SELECT id, 'created', 'done', 'Imported from Linear CORE-150', 'linear', 'import', '2026-10-05T22:14:12.394Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 151, 'CI: e2e on Chromium only for work-branch pushes, all 3 browsers on dev/prod', 'The CI `test` job takes 20–30 min on every push of every `worktree-*` branch. About 14 min of that is the Playwright e2e on chromium + firefox + webkit (plus \~40 s installing the three browsers). Everything else takes \~4 min. With several threads in parallel, feedback is slow and the session waits on CI before handing over the PR link.', '* In `.github/workflows/ci.yml`, on `worktree-*`, `worker/*` and `claude/*` pushes: install and run Chromium only (`--project=chromium` or equivalent).
* On `dev` and `prod` pushes, and on PRs from other heads (renovate), keep the full 3-browser matrix.
* Does not touch the lines [CORE-144](https://linear.app/neosleep/issue/CORE-144/deploy-only-the-app-that-changed-stop-duplicate-ci-on-the-promote-pr) (PR [lukasz512/NeoSleep#455](https://linear.app/neosleep/review/core-144-deploy-only-the-app-that-changed-skip-duplicate-ci-on-the-4fa5d07ee648)) changes.',
    '* A work-branch CI run finishes its test job in ≤10 min.
* A `dev` push run still executes the e2e on all 3 browsers (visible in the log).', 'needs_review', 0, '{}'::text[],
    '[{"kind":"artifact","url":"https://claude.ai/artifact/L1NvPrXBmFvPgUWbixVhV3","title":"Artifact: CORE-150 + CORE-151 Lighter local dev and CI"}]'::jsonb, NULL, 'linear_import', 'CORE-151', 'linear',
    '2026-10-05T22:14:15.632Z'::timestamptz, '2026-10-05T22:14:15.632Z'::timestamptz, '2026-10-05T22:14:15.632Z'::timestamptz, NULL)
