SELECT id, 'created', 'needs_review', 'Imported from Linear CORE-151', 'linear', 'import', '2026-10-05T22:14:15.632Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 152, 'CI: run only what a change can break (path gate + related e2e on work branches)', 'Every push of every work branch runs the full CI: lint + typecheck of all workspaces, all API tests, the whole e2e suite. On 2026-10-05 up to 9 such runs were in flight at once, 20-30 min each, some sessions waited about an hour (reruns, cancels by the next merge to dev). A docs-only or .claude-only change costs the same as a feature.', '* Path gate inside the `test` job (the required check must still report): diff vs origin/dev touches only docs/, \*.md, .claude/ → skip install/test steps, report success.
* Work branches: e2e = specs picked by infrastructure/scripts/related-e2e.mjs (extended to API-backed specs) + auth.spec smoke; full suite stays on dev/prod and PRs.
* Split the job into parallel jobs (static checks · api tests · e2e) so a red lint fails in 2 min, not after 20.
* Cache Playwright browsers (\~40 s per run).',
    '* A docs-only push finishes CI in under 2 min.
* A typical work-branch run takes 10 min or less; dev/prod still run everything.', 'done', 0, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/472","title":"CORE-152 Fix red dev CI after CORE-152 + nightly time limit"},{"kind":"artifact","url":"https://claude.ai/artifact/6ZCcgm6jAuPoLBWVRE75fZ","title":"Artifact: CORE-152 follow-up: dev green again"},{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/466","title":"CORE-152 Targeted CI tests + one diagnostics group per error"},{"kind":"artifact","url":"https://claude.ai/artifact/FfUVkdHJqU99kf4eJYhcU9","title":"Artifact: CORE-152 Targeted CI tests"}]'::jsonb, NULL, 'linear_import', 'CORE-152', 'linear',
    '2026-10-05T22:26:18.324Z'::timestamptz, '2026-10-05T23:50:13.227Z'::timestamptz, '2026-10-05T23:50:13.227Z'::timestamptz, '2026-10-05T23:50:13.227Z'::timestamptz)
  ON CONFLICT DO NOTHING
  RETURNING id
)
