SELECT id, 'created', 'done', 'Imported from Linear CORE-158', 'linear', 'import', '2026-10-05T23:37:50.230Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 159, 'Patient Detalles: "Próxima cita" tile includes events and opens in place', 'On the patient card (Detalles), the "Próxima cita" tile only reads appointments. Events (Evento) booked for the patient never show up there and never update it. Tapping the tile leaves the patient card and jumps to the calendar, so changing the visit takes several steps.', '* The tile shows the soonest upcoming scheduled item, appointment or event.
* Tapping it opens the item on the patient card itself: the appointment detail dialog (complete / reschedule / no-show / cancel) or the event form (edit).
* Rows in the Citas and Eventos groups open the same dialogs.
* After any change, the tile and the lists refresh without F5.',
    '* An event booked for the patient updates the tile.
* Tapping the tile lets you reschedule or cancel without leaving the card, and the tile shows the new date afterwards.
* Covered by PatientDetailsTab specs.', 'done', 2, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/467","title":"CORE-159 Next-visit tile counts events and opens the visit on the patient card"},{"kind":"artifact","url":"https://claude.ai/artifact/EZcdVMHSXpRJN5mtvLhutk","title":"Artifact: CORE-159 Próxima cita tile"}]'::jsonb, NULL, 'linear_import', 'CORE-159', 'linear',
    '2026-10-05T23:43:00.878Z'::timestamptz, '2026-10-06T00:02:20.838Z'::timestamptz, '2026-10-06T00:02:20.838Z'::timestamptz, '2026-10-06T00:02:20.838Z'::timestamptz)
