SELECT id, 'created', 'done', 'Imported from Linear CORE-162', 'linear', 'import', '2026-10-06T00:21:38.377Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 163, 'Theme switch: smooth crossfade, menu stays on top, follow OS dark/light live', 'Switching light/dark/auto in the account menu jerks the layout: the page sheet, top bar and bottom nav carry permanent view-transition names, so during the theme view transition they are painted in the overlay above the menu, and Vuetify''s colors change before the "old" frame is captured (mixed half-switched frame). Also `startSystemListener()` is never called anywhere, so "Auto" does not follow the OS when the device switches dark/light while the app is open.', '* Theme store: apply data-theme AND the Vuetify theme inside one view-transition callback (new `appliedMode`), wait a tick before the new frame is captured.
* During a theme transition (`html[data-theme-transition]`) all named view-transition groups are disabled → one full-page crossfade; the open menu stays on top.
* Store starts the OS listener itself (prefers-color-scheme change → live switch in Auto).',
    '* Theme switch is one smooth crossfade with no jump; the user menu stays visible and open on top.
* With Auto selected, toggling OS dark mode switches the app live.
* Unit tests cover appliedMode ordering + system listener auto-start.', 'done', 3, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/474","title":"CORE-163 Smooth theme crossfade, menu on top, Auto follows the OS (CORE-163)"},{"kind":"artifact","url":"https://claude.ai/artifact/9UeWV9XADyVFp6tk2dwKEp","title":"Artifact: CORE-163 Smooth Theme Switch"}]'::jsonb, NULL, 'linear_import', 'CORE-163', 'linear',
    '2026-10-06T00:37:44.820Z'::timestamptz, '2026-10-06T01:39:23.144Z'::timestamptz, '2026-10-06T01:39:23.144Z'::timestamptz, '2026-10-06T01:39:23.144Z'::timestamptz)
  ON CONFLICT DO NOTHING
  RETURNING id
)
