    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 169, 'Reschedule fails when the confirm request goes out at once (SQL double assignment)', 'Rescheduling an appointment to a time inside the confirm window (e.g. tomorrow) fails with "No se pudo guardar la cita". The API returns 503: `setAppointmentPatientToken` builds `UPDATE appointment SET … confirm_request_sent_at = NULL, … confirm_request_sent_at = now()`, which Postgres rejects with 42601 "multiple assignments to same column". Seen on pwa-dev 2026-10-06 01:06 UTC.', 'In `apps/api/src/db/appointmentPatientLink.ts`, a column that this email stamps is set to `now()` instead of being cleared, so each column is assigned once. Add a DB-backed test for a reschedule inside the confirm window.',
    '* Rescheduling to tomorrow saves on the first try and the patient gets the reschedule email
* Test reproduces the 42601 before the fix and passes after', 'done', 2, ARRAY['Bug']::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/483","title":"CORE-169 Fix reschedule inside the confirm window (CORE-169)"},{"kind":"artifact","url":"https://claude.ai/artifact/DGxXoeaPTjxey5yv1vhnwZ","title":"Artifact: CORE-169 Reschedule Save Fix"}]'::jsonb, NULL, 'linear_import', 'CORE-169', 'linear',
    '2026-10-06T01:10:48.011Z'::timestamptz, '2026-10-06T01:24:31.773Z'::timestamptz, '2026-10-06T01:24:31.773Z'::timestamptz, '2026-10-06T01:24:31.773Z'::timestamptz)
