SELECT id, 'created', 'done', 'Imported from Linear CORE-171', 'linear', 'import', '2026-10-06T01:22:42.331Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 172, 'QR "sign on your phone" next to every signature pad on desktop', '[CORE-166](https://linear.app/neosleep/issue/CORE-166/partner-agreement-sign-on-phone-via-qr-from-desktop) added a QR next to the mouse pad only for the partner agreement. Every other signature drawn on a computer is still mouse-only: the doctor''s signature before printing the Historia clínica (DoctorSignatureDialog) and the patient''s consent signature when /q is opened on a computer.', '* One shared mechanism: tenant table `signature_handoff` (purpose, hashed sign token + hashed pickup token, 15 min, single use, signature cleared at pickup, audit row)
* Start per context: partner = invite token, patient = questionnaire token, doctor = session; phone + pickup routes are generic
* Generic phone page `/sign#<token>` ([CORE-166](https://linear.app/neosleep/issue/CORE-166/partner-agreement-sign-on-phone-via-qr-from-desktop)''s /partner-sign redirects there)
* Shared desktop component `PhoneSignPanel` next to every SignaturePad on desktop
* Partner flow moves off invite_tokens.metadata onto the table',
    '* Desktop: pad + QR side by side in the partner agreement, doctor print signature and patient /q consent
* The phone signature lands in the right pad on the computer; codes expire, work once, sign only
* API tests on real DB + PWA tests green', 'building', 0, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/489","title":"CORE-172 QR sign-on-phone next to every signature pad on desktop"},{"kind":"artifact","url":"https://claude.ai/artifact/5g1wyYLJ5dqh2C8KDu46Xg","title":"Artifact: CORE-172 QR Next to Every Signature"}]'::jsonb, NULL, 'linear_import', 'CORE-172', 'linear',
    '2026-10-06T01:58:42.825Z'::timestamptz, '2026-10-06T01:58:42.825Z'::timestamptz, '2026-10-06T01:58:42.825Z'::timestamptz, NULL)
