INSERT INTO platform.work_item_event (item_id, kind, to_status, body, actor, actor_kind, created_at)
SELECT id, 'created', 'building', 'Imported from Linear CORE-172', 'linear', 'import', '2026-10-06T01:58:42.825Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 173, 'Doctor account not linked to practitioner → doctor sees nothing (Dra. Lorena, pwa-dev)', 'Dra. Lorena (doctor) gets "Sin acceso" on every screen on pwa-dev. Cloud Run logs 2026-10-06 05:15–05:22 UTC: every data call returns 403 "This doctor account is not linked to a practitioner record" (entityAccess.ts resolveViewer, [CORE-104](https://linear.app/neosleep/issue/CORE-104/doctor-sees-only-own-patients-row-level-access-policy-for-all-entities)). She does have an assigned patient, so her practitioner row exists but her users row points to a different identity.
Likely cause: createPractitioner stores [identities.email](<http://identities.email>) as typed (trim only), while insertStaffUser lowercases it. A mixed-case email therefore never hits ON CONFLICT (email), so invite provisioning creates a second identity, and the user and the practitioner end up split.', '* One email normalizer (trim + lowercase) for every identity write: practitioner, lead, user, and updates.
* Migration: relink each doctor user with no practitioner to the single practitioner whose identity email matches case-insensitively. Audit-logged, no deletes.
* Provisioning asserts that the user''s and the practitioner''s identity are the same, so it fails loudly at invite time and never at login.
* An unlinked doctor at login triggers an automatic admin report (Issues + admin notification), once per user per day, and the doctor sees a clear message.',
    '* Integration tests: mixed-case email invite → linked; migration relinks a split pair; an unlinked doctor creates one admin report.
* Dra. Lorena sees her patient on pwa-dev.', 'done', 1, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/491","title":"CORE-173 Doctor login linked to practitioner; separate sign-in email"},{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/490","title":"CORE-173 Doctor login linked to practitioner; separate login email"},{"kind":"artifact","url":"https://claude.ai/artifact/Vm2FsKEPm5sVvvP4JsJ2h6","title":"Artifact: CORE-173 Doctor Login Linked To Practitioner"}]'::jsonb, NULL, 'linear_import', 'CORE-173', 'linear',
    '2026-10-06T08:34:14.638Z'::timestamptz, '2026-10-06T09:25:28.807Z'::timestamptz, '2026-10-06T09:25:28.807Z'::timestamptz, '2026-10-06T09:25:28.807Z'::timestamptz)
  ON CONFLICT DO NOTHING
  RETURNING id
)
INSERT INTO platform.work_item_event (item_id, kind, to_status, body, actor, actor_kind, created_at)
SELECT id, 'created', 'done', 'Imported from Linear CORE-173', 'linear', 'import', '2026-10-06T08:34:14.638Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 174, 'Smoke API waits forever after a merge commit (api-deploy-commit needs --first-parent)', 'Post-deploy smoke (dev) `api` job hangs 20 min and fails after a PR merge into dev. deploy-api deploys the merge commit (e.g. 72e060f), but `api-deploy-commit.mjs` runs `git log -1 -- <paths>` without `--first-parent`; history simplification drops the merge commit (TREESAME to its second parent) and returns the inner commit (328584f), which the API never serves. Seen on PR #492/#493.', 'Add `--first-parent` to the git log call so each dev commit (incl. merges) is diffed against the previous dev state — the same thing the push path filter does. Regression test with a real merge commit.',
    '* `node infrastructure/scripts/api-deploy-commit.mjs 72e060f` prints 72e060f
* test covers a merge that touches API paths
* smoke `api` green on the next API-touching merge into dev', 'done', 2, '{}'::text[],
    '[{"kind":"artifact","url":"https://claude.ai/artifact/3vC8ueKfyedRDS1kgxSbNZ","title":"Artifact: CORE-174 Smoke waits for the right API commit"},{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/494","title":"fix(ci): smoke waits for the merge commit deploy-api deployed (CORE-174)"}]'::jsonb, NULL, 'linear_import', 'CORE-174', 'linear',
    '2026-10-07T14:53:25.896Z'::timestamptz, '2026-10-07T15:29:10.402Z'::timestamptz, '2026-10-07T15:29:10.402Z'::timestamptz, '2026-10-07T15:29:10.402Z'::timestamptz)
  ON CONFLICT DO NOTHING
  RETURNING id
)
INSERT INTO platform.work_item_event (item_id, kind, to_status, body, actor, actor_kind, created_at)
SELECT id, 'created', 'done', 'Imported from Linear CORE-174', 'linear', 'import', '2026-10-07T14:53:25.896Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 175, 'Slim the Claude dev process: cheaper Change Index, lighter gate, fewer skills', 'Claude usage runs out fast. In the last 40 sessions, 97% of the cost was re-reading context. On every ship, reading the Change Index (625 KB) adds \~300k tokens. The Stop gate blocked 56 times. 24 of 26 skills were never used.', 'Decisions slim-r1 (all "more"):

* D1 Change Index → a tiny page whose rows live in the artifact DB; adding a row is one ArtifactData write, no read or republish
* D2 Full artifact only for UI/feature changes; small changes get one Linear comment with the PR link
* D3 Stop gate runs only fast checks (lint + typecheck on changed files, markers); tests run on pre-push/CI
* D4 Personas merged into /perspective; arch and linear-worker slimmed
* D5 1 ticket = 1 session: after push, artifact check → handoff → suggest /clear; warning at 120k context
* Defaults: never Read the saved index file; MEMORY.md < 8 KB',
    '* A ship adds < 5k tokens for the index
* The Stop gate never runs tests
* The skill list has ≤ 12 project skills
* The post-push hook fires and the hook tests pass', 'needs_review', 0, '{}'::text[],
    '[]'::jsonb, NULL, 'linear_import', 'CORE-175', 'linear',
    '2026-10-07T18:50:25.882Z'::timestamptz, '2026-10-07T18:50:25.882Z'::timestamptz, '2026-10-07T18:50:25.882Z'::timestamptz, NULL)
  ON CONFLICT DO NOTHING
  RETURNING id
)
INSERT INTO platform.work_item_event (item_id, kind, to_status, body, actor, actor_kind, created_at)
SELECT id, 'created', 'needs_review', 'Imported from Linear CORE-175', 'linear', 'import', '2026-10-07T18:50:25.882Z'::timestamptz FROM ins
UNION ALL SELECT id, 'comment', NULL, 'Liczba skilli spadła z 26 do 15, więc każda sesja ładuje około 107 KB zamiast 230 KB. Zmiany bez UI dostają teraz jeden komentarz w Linear zamiast pełnego Artifactu. Stop gate sprawdza tylko lint i typecheck zmienionych workspace''ów, a testy i depcruise przeszły do pre-push. Auto-compact odpala się sam przy około 180k (`CLAUDE_CODE_AUTO_COMPACT_WINDOW=200000`), a nie dopiero przy limicie 1M. Hook po pushu prowadzi przez handover, potem handoff, potem /clear.
PR (tworzy Łukasz): [compare dev...worktree-core-175-slim-claude-process](https://github.com/lukasz512/NeoSleep/compare/dev...worktree-c…', 'linear', 'import', '2026-10-07T19:23:54.243Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 176, 'Admin feature switches screen + admin access to Doctor Panel', 'Feature flags (e.g. doctorPanel) sit in app_config.integrations.features and can only be changed with SQL on prod. The admin can''t see the Doctor Panel (the API is requireRole("doctor")). platform.feature_flags already exists but nothing reads it.', 'Decisions in form admin-features-r1 (all "more"):

* D1: flags move to platform.feature_flags (enabled + locked), every change is written to audit_log, doctorPanel is migrated, and the old app_config key is removed. Feature keys are registered in code with a dev/prod default.
* D2: two levels. The platform owner (platform.users) sets locked; the tenant admin toggles unlocked flags at /settings/features.
* D3: the admin sees the Doctor Panel totalled across all doctors by default, plus a "view as Dr X" picker. Read-only; every view is written to audit_log.
* When a flag is off, the API returns 403. The PWA refetches flags after a toggle.',
    'The admin turns doctorPanel on and off in the app, without SQL, and the doctor sees the change after a reload. The admin sees the Panel as a total and per doctor. Tests cover the 403, locked flags, audit, and the migration.

Story: docs/stories/admin-feature-switches.md', 'backlog', 0, '{}'::text[],
    '[]'::jsonb, NULL, 'linear_import', 'CORE-176', 'linear',
    '2026-10-07T19:07:48.404Z'::timestamptz, '2026-10-07T19:07:48.404Z'::timestamptz, '2026-10-07T19:07:48.404Z'::timestamptz, NULL)
  ON CONFLICT DO NOTHING
  RETURNING id
)
INSERT INTO platform.work_item_event (item_id, kind, to_status, body, actor, actor_kind, created_at)
SELECT id, 'created', 'backlog', 'Imported from Linear CORE-176', 'linear', 'import', '2026-10-07T19:07:48.404Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 177, 'Platform kanban in admin (replaces Linear) — v1 board', 'Linear''s free plan caps us at 250 issues, and the nightly worker can''t rely on it. Łukasz also wants to manage every client (CORE, NEO, AJM, …) in one place, inside the platform.', '* Platform schema: `platform.work_team` (key, name, optional company/tenant link), `platform.work_item` (KEY-n, title, Problem/Change/Done when, status, priority, links), `platform.work_item_event` (audit trail of every status change and comment).
* API `/api/platform/work-items`, open to platform admins only (tenants get 403). The worker gets a scoped service token.
* PWA `/platform/board`: kanban with the columns Triage · Backlog · To spec · Spec ready · Approved for dev · Building · Needs Review · Done, filtered by team. On a phone the columns become a list grouped by status. Cards show artifact, PR and CI links, and the board has keyboard shortcuts.
* Slimmed import of the Linear export (no AI noise); KEY-n numbering continues.',
    '* Integration tests on a real database cover the 403 for tenants, a status move writing an audit event, and KEY-n numbering continuing per team.
* The board runs on pwa-dev with the imported history.
* The worker can read and move items through the API with its token.', 'backlog', 2, '{}'::text[],
    '[]'::jsonb, NULL, 'linear_import', 'CORE-177', 'linear',
    '2026-10-07T19:13:45.076Z'::timestamptz, '2026-10-07T19:13:45.076Z'::timestamptz, '2026-10-07T19:13:45.076Z'::timestamptz, NULL)
  ON CONFLICT DO NOTHING
  RETURNING id
)
