SELECT id, 'created', 'backlog', 'Imported from Linear CORE-177', 'linear', 'import', '2026-10-07T19:13:45.076Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('CORE', 178, 'Tell dev and prod PWA apart: DEV badge on the icon + version in the name', 'An installed pwa-dev and pwa (prod) look identical on the home screen: same icon, same "NeoSleep" name. Testers and Łukasz can''t tell which one they opened, so they risk entering real data in dev or testing in prod.', 'Dev builds (VITE_APP_CHANNEL=dev) get a different manifest: an icon with a visible DEV badge (generated at build time from the brand icon) and a name carrying the version, e.g. "NeoSleep DEV 1.1.0". Prod stays as it is. Step 1: a mockup Artifact with the variants for Łukasz to choose from.',
    '* Łukasz has picked a variant in the mockup Artifact
* The dev build''s manifest has the badged icons + versioned name, prod''s manifest is unchanged (test)
* The installed pwa-dev app is visibly different from prod on iOS and Android', 'backlog', 0, '{}'::text[],
    '[{"kind":"artifact","url":"https://claude.ai/artifact/NjbNKgh3B3JwusoFydrt3K","title":"Artifact: CORE-178 Dev vs Prod App Icon (mockup)"}]'::jsonb, NULL, 'linear_import', 'CORE-178', 'linear',
    '2026-10-07T19:18:44.602Z'::timestamptz, '2026-10-07T19:18:44.602Z'::timestamptz, '2026-10-07T19:18:44.602Z'::timestamptz, NULL)
  ON CONFLICT DO NOTHING
  RETURNING id
)
