SELECT id, 'created', 'to_spec', 'Imported from Linear NEO-86', 'linear', 'import', '2026-09-26T12:58:33.234Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 87, 'PWA installable: fix missing manifest icons + "Install app" button next to avatar', '**Problem**

* The PWA is not installable and its icon is broken: the manifest references `/icon-192.png`, `/icon-512.png`, `/apple-touch-icon.png`, `/favicon.ico`, but `apps/pwa/public/` does not exist — pwa-dev returns the SPA `index.html` (text/html) for every icon URL. Chrome therefore refuses the install prompt, and iOS home-screen icon falls back to a screenshot.
* There is no in-app way to install — users must know the browser menu.

**Change**

* Generate real PNG icons (192, 512, maskable 512, apple-touch 180, favicon) from the brand icon SVG, served from `apps/pwa/public/`; add `<link rel="icon">` / `apple-touch-icon` / `theme-color` to `index.html`.
* After login, an "Install app" button in the top bar next to the avatar: uses `beforeinstallprompt` on Chrome/Edge/Android; on iOS Safari (no prompt API) opens a short "Share → Add to Home Screen" hint. Hidden when already running standalone or when install isn''t possible.

**Done when**

* Lighthouse/Chrome DevTools "Installable" passes on pwa-dev; icons return image/png.
* Button visible after login on a supported browser, triggers install, disappears once installed; not shown in the installed app.', NULL,
    NULL, 'done', 0, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/270","title":"NEO-87 Always offer install on Chrome/Edge + catch install event early"},{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/256","title":"NEO-87 Installable PWA: device-aware Add card, menu entry, desktop QR, icons"},{"kind":"artifact","url":"https://claude.ai/artifact/AC4ETz15cmVSRr7v4sRdxR","title":"Artifact: NEO-87 Installable PWA"}]'::jsonb, NULL, 'linear_import', 'NEO-87', 'linear',
