WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 99, 'Patient QR forms: signature hint hides while signing + toast validation, Send locked until complete', '**Problem**

1. Consent step on the patient QR page (/q): the "Firma aquí con tu dedo" hint inside the signature box stays visible while the patient is drawing. It only disappears once the finger is lifted.
2. Patient questionnaires (medical history, STOP-Bang): validation is shown as inline alerts, and Send is only disabled by the data-consent checkbox. It is not disabled while questions are still unanswered.

**Change** (Łukasz, 2026-09-26)

* The signature hint disappears the moment a stroke begins.
* All yes/no questions stay required. Validation feedback uses the app''s toast notifications instead of inline alerts.
* Send (and Sign & continue) stays locked until the non-empty validation passes: every question answered + consent ticked (or a signature drawn).

**Done when**

* The hint disappears on first touch. Clear brings it back.
* Send is locked until every question is answered and consent is ticked. Tapping it while locked shows a toast saying what''s missing and highlights the unanswered questions.
* The before/after is shown in the Artifact.', NULL,
    NULL, 'done', 0, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/263","title":"NEO-99 Patient QR forms: toast validation, Send locked until complete"},{"kind":"spec","url":"https://claude.ai/artifact/WuQPwpMhZzLch81sNCMuWu","title":"Artifact: NEO-99 Patient Form Validation"}]'::jsonb, NULL, 'linear_import', 'NEO-99', 'linear',
