WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 100, 'Patient consent signature: full-screen signing on phones (landscape on Android, adaptive on iOS)', 'On the patient QR page (consent step), "Clear" sits \~8 px above "I sign and continue". One careless tap wipes the signature or submits the wrong one. The inline pad is also small and the page scrolls while signing.

Options explored: [https://claude.ai/artifact/CtNpPkJWemEbQU7Nsu64Rg](<https://claude.ai/artifact/CtNpPkJWemEbQU7Nsu64Rg>) — Łukasz picked **C (full-screen landscape) where possible, otherwise B (full-screen portrait)**, one version for both Android and iOS (rotate where the browser allows), phones only.', '* Phones: the signature box becomes a "Tap to sign" button that opens a full-screen signing sheet. Clear and "Use this signature" live at opposite ends of the screen.
  * **Android (Chrome)**: enter browser fullscreen and lock orientation to landscape (Screen Orientation API). If the lock is refused → portrait full-screen.
  * **iOS (Safari)**: no orientation lock and no element fullscreen on iPhone. The sheet fills the viewport; in landscape it uses the wide layout, in portrait it shows the portrait layout plus a hint "Turn your phone sideways for more space". Layout follows live rotation.
* Tablets/desktop: inline pad stays, Clear moves inside the pad corner (existing `clearPlacement="overlay"`), "I sign and continue" disabled until signed.',
    '* Clear can never be hit next to the submit action on any device.
* Android phone: tap → landscape full-screen; iPhone: tap → full-screen, wide when rotated.
* Submitted signature is still a PNG, now cropped to the ink (as [NEO-51](https://linear.app/neosleep/issue/NEO-51/partner-onboarding-countersigned-agreement-dpa-e-signature-privacy)).
* EN/PL/MX keys added.', 'done', 0, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/268","title":"NEO-100 Bigger signatures on signed PDFs (26mm box, 80% width)"},{"kind":"artifact","url":"https://claude.ai/artifact/DGrcUGHw8hMrW1ggoNPcau","title":"Artifact: NEO-100 Bigger PDF Signatures"},{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/264","title":"NEO-100 Full-screen patient signature on phones"},{"kind":"artifact","url":"https://claude.ai/artifact/Jbd6JjMweoyksd9j7WJ9hQ","title":"Artifact: NEO-100 Full-Screen Signature"}]'::jsonb, NULL, 'linear_import', 'NEO-100', 'linear',
    '2026-09-26T15:23:31.027Z'::timestamptz, '2026-09-26T16:33:51.271Z'::timestamptz, '2026-09-26T16:33:51.271Z'::timestamptz, '2026-09-26T16:33:51.271Z'::timestamptz)
