SELECT id, 'created', 'building', 'Imported from Linear NEO-101', 'linear', 'import', '2026-09-26T15:32:37.635Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 102, 'Account menu rebuild: segmented theme (Auto default) + language, change password, app version', '**Problem**
The account menu (top-right avatar) is three unlabeled round icons (theme, language, log out). The app version sits as a wrapped two-line grey label in the sidebar footer and is missing on phones. There is no in-app way to change your password.

**Change** (decided 2026-09-26, option C in the proposal artifact [https://claude.ai/artifact/PsaWPdgfuqQXjVu1NnqoqA](<https://claude.ai/artifact/PsaWPdgfuqQXjVu1NnqoqA>))

* Account menu = header (avatar, name, email, role, region) + Theme segmented control (Light / Dark / Auto) + Language segmented control + "Change password" (hidden for users without a password, e.g. Google-only) + separate "Log out" button + app version line at the bottom.
* Phone: the same menu content.
* Auto (follow OS) is the default for users who never picked a theme. Stored per device in localStorage (existing theme store); DB persistence not needed for now.
* Version label removed from the sidebar footer; a small DEV badge next to the logo on non-prod builds.

**Done when**

* Menu matches option C on desktop and phone, all copy in en/pl/mx.
* Theme choice persists across reloads; a fresh browser starts on Auto.
* Change password works from the menu and returns to the app.
* Version visible in the menu on both breakpoints; DEV badge only on non-prod.', NULL,
    NULL, 'done', 0, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/276","title":"NEO-102 Account menu: theme (Auto default), language, password, version"},{"kind":"artifact","url":"https://claude.ai/artifact/TCkvA663WZV6s6ZiKkigLf","title":"Artifact: NEO-102 Account Menu"}]'::jsonb, NULL, 'linear_import', 'NEO-102', 'linear',
    '2026-09-26T16:44:13.840Z'::timestamptz, '2026-09-26T17:52:40.579Z'::timestamptz, '2026-09-26T17:52:40.579Z'::timestamptz, '2026-09-26T17:52:40.579Z'::timestamptz)
