SELECT id, 'created', 'done', 'Imported from Linear NEO-102', 'linear', 'import', '2026-09-26T16:44:13.840Z'::timestamptz FROM ins
UNION ALL SELECT id, 'comment', NULL, 'Decided (Łukasz, 2026-09-26):
1. Auto is the default theme for everyone who never picked one, not only new users.
2. The theme choice is saved per device (localStorage), not in the database.
3. After a password change the user signs in again on every device, including after the forced first-login change.', 'linear', 'import', '2026-09-26T17:37:41.990Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 103, 'Login backdrop: delta-wave dots + asymmetric orbs, dots "inhaled" by the card while signing in', 'The login backdrop (dot grid + three teal orbs) reads as a flat grid on the whole screen plus one big blob behind the card. While signing in, the dots don''t react at all, so nothing tells the user "the card took your data".

## Decisions (Łukasz, 2026-09-26, chosen from two design Artifacts)

* Variant **B "Fale delta"**: [https://claude.ai/artifact/4n4KWWqepnaQAea22W1G7i](<https://claude.ai/artifact/4n4KWWqepnaQAea22W1G7i>)
  * Dot grid: spacing **40 px**, dot **1.8 → 4.5 px** (rest → pointer peak), resting opacity 0.32.
  * Ambient motion: dots move vertically (±3.5 px + ±2 px, two superposed sines, 9 s / 13 s) with the brighter crest travelling left→right, row phase offset 0.35 — like a slow-wave (delta) EEG trace. Phase is integrated per frame (no clock × speed jumps).
  * Orbs: asymmetric rule-of-thirds composition (big orb off the bottom-right corner, medium under the logo, small at the card''s lower-left corner), slow elliptical drift 40/55/33 s, thin white orbit ring, busy ring pulse.
* Loading choreography **2 "Wdech karty"**: [https://claude.ai/artifact/BqXJB3CUGx1tjDEMuvXKdo](<https://claude.ai/artifact/BqXJB3CUGx1tjDEMuvXKdo>)
  * On sign-in (busy): dots are drawn toward the card (up to 90 px), glow and shrink to zero — nearest first, **1.5 s** total.
  * On error: the card "exhales" them back outward with a slight overshoot, **1.5 s** total. Reversal mid-animation starts from where each dot currently is.
* Pointer repulsion physics unchanged.', NULL,
    '* Login screen on pwa-dev shows the new dots/orbs; sign-in with wrong password shows the inhale then exhale; success path still plays the existing orb exit.
* prefers-reduced-motion: static frame, no inhale motion.
* Boot splash (static HTML backdrop) matches the new orb layout so the takeover has no jump.', 'done', 0, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/293","title":"NEO-103 Login orbs: light mint small orb on phones"},{"kind":"artifact","url":"https://claude.ai/artifact/A31J7DbWDNz4F6UoUMgUeo","title":"Artifact: NEO-103 Phone Orb Contrast"},{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/286","title":"NEO-103 Login orbs: layout B for the third orb on phones"},{"kind":"artifact","url":"https://claude.ai/artifact/FD4fuwWATyTh3cNhTTRvt9","title":"Artifact: NEO-103 Three Orbs On Phone"},{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/277","title":"NEO-103 Login orbs: center with margins so the prod build keeps them in place"},{"kind":"artifact","url":"https://claude.ai/artifact/TRq5iGab5gcMWToiULCS8N","title":"Artifact: NEO-103 Big Orb Back On Screen"},{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/269","title":"NEO-103 Login backdrop: delta-wave dots, asymmetric orbs, card inhale on sign-in"},{"kind":"artifact","url":"https://claude.ai/artifact/4t86G5o9bY8B8tRHRiFVKK","title":"Artifact: NEO-103 Login Backdrop Delta Waves"}]'::jsonb, NULL, 'linear_import', 'NEO-103', 'linear',
    '2026-09-26T16:47:13.238Z'::timestamptz, '2026-09-26T22:33:48.466Z'::timestamptz, '2026-09-26T22:33:48.466Z'::timestamptz, '2026-09-26T22:33:48.466Z'::timestamptz)
