SELECT id, 'created', 'done', 'Imported from Linear NEO-122', 'linear', 'import', '2026-09-26T21:59:34.970Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 123, 'QR dialog still takes ~10 s to close after the scan: tell the server on page open, check at a steady 2 s', 'On pwa-dev, [NEO-117](https://linear.app/neosleep/issue/NEO-117/qr-dialog-wait-5-s-then-check-every-2-s-whether-the-patient-opened-the) still needs about 10 s between the scan and the QR dialog closing (Łukasz, 2026-09-27). Two causes:

1. The checks run every \~2.7 s rather than 2 s, because each check waits for the server''s answer before starting the next 2 s.
2. The server only learns the link was opened once the phone has downloaded and started the whole app and requested the form, which takes several seconds on a phone.', '* Checks run at a steady 2 s from the moment they start, whatever the server''s response time.
* The patient page tells the server "opened" as soon as the page HTML arrives, before the app itself has loaded.',
    'Measured on pwa-dev: the QR closes about 2 s after the phone starts opening the link (after the first 5 s).', 'done', 0, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/294","title":"NEO-123 QR dialog closes faster: early ''opened'' ping, steady 2 s checks"}]'::jsonb, NULL, 'linear_import', 'NEO-123', 'linear',
    '2026-09-26T22:12:47.738Z'::timestamptz, '2026-09-26T22:48:45.710Z'::timestamptz, '2026-09-26T22:48:45.710Z'::timestamptz, '2026-09-26T22:48:45.710Z'::timestamptz)
