INSERT INTO platform.work_item_event (item_id, kind, to_status, body, actor, actor_kind, created_at)
SELECT id, 'created', 'done', 'Imported from Linear NEO-134', 'linear', 'import', '2026-09-27T01:05:57.907Z'::timestamptz FROM ins
UNION ALL SELECT id, 'comment', NULL, 'Decided (Łukasz, 2026-09-28): dropping the patient''s in-app row is fine. The patient gets an **email** about the order status change instead → NEO-172 (depends on NEO-139 email channel + NEO-146 consent).', 'linear', 'import', '2026-09-28T14:25:28.935Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 141, 'Doctor events: appointments, patient forms/signatures, new result or patient, OrthoApnea orders', 'Doctors, the main recipients, get almost nothing today (only appointments and orders, in the admin-only bell).', 'Add catalog entries and producers for the doctor role:

* appointment booked / rescheduled / cancelled (migrated in [NEO-134](https://linear.app/neosleep/issue/NEO-134/engine-core-event-catalog-notify-and-delivery-log));
* a patient completed a QR form or signed a document;
* a new sleep study result is ready, or a new patient was assigned or referred;
* an OrthoApnea order status changed.

Rules:

* Every event uses a generic PHI-free title and body and a deep link to the record.
* Default channels: in-app + push, and email only via escalation.
* The recipient is resolved from the record: the treating doctor, falling back to the patient''s assigned doctor.',
    '* Each event creates exactly one inbox item for the right doctor and none for others (tenant + ownership test).
* The deep link opens the record.
* [NEO-28](https://linear.app/neosleep/issue/NEO-28/send-booking-confirmation-emails-to-hcp-and-patient)''s in-app part is covered and noted on [NEO-28](https://linear.app/neosleep/issue/NEO-28/send-booking-confirmation-emails-to-hcp-and-patient).', 'backlog', 2, ARRAY['Notifications', 'Feature']::text[],
    '[]'::jsonb, NULL, 'linear_import', 'NEO-141', 'linear',
    '2026-09-27T01:06:38.568Z'::timestamptz, '2026-09-27T01:06:38.568Z'::timestamptz, '2026-09-27T01:06:38.568Z'::timestamptz, NULL)
  ON CONFLICT DO NOTHING
  RETURNING id
)
