WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 178, 'Patient email sender: "<clinic> | NeoSleep" <notifications@> instead of noreply', 'Resend flags `noreply@mail.neosleepcare.com` as "Needs attention" because a no-reply address lowers inbox trust. Patients also don''t recognize "NeoSleep"; they know their clinic.', '* The sending address is now `notifications@mail.neosleepcare.com`, set in `infrastructure/cloud-run/*.env.yaml` and `.env.example`.
* The questionnaire link email is sent From `"<clinic> | NeoSleep"`. Reply-To stays the clinic.
