WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 179, 'DPIA draft (GDPR art. 35) + MX security-measures document', 'We are about to process health data at scale: sleep studies, questionnaires, photos, and later research. For that kind of processing GDPR art. 35 almost certainly requires a DPIA before processing starts. MX (LFPDPPP) requires documented security measures. We have neither document.', '/legal prepares both drafts in `docs/legal/`:

* **DPIA**: what data is processed and for which purposes, the legal basis for each purpose, data flows (PWA → API → Supabase/GCP, Resend, OrthoApnea), risks for the patient, mitigations (PHI-free notifications, tenant isolation, audit log, backup encryption), retention per country (PL 20 years, MX 5 years), and residual risk.
* **MX security measures**: administrative, physical and technical controls, and ARCO handling.

Both documents fix the answers that the rest of the epic builds on: the effect of withdrawing consent, retention, and who may see consents.

This is not legal advice. An optional external review is [CORE-49](https://linear.app/neosleep/issue/CORE-49/optional-external-legal-review-of-consent-texts-before-production).',
    '* Both drafts are in the repo.
* Every purpose from round 1 (health data, contact channels, partners, marketing, research, photos) has a legal basis and a retention period.
* Open risks are listed for Łukasz.', 'backlog', 1, ARRAY['Privacy']::text[],
    '[]'::jsonb, NULL, 'linear_import', 'NEO-179', 'linear',
    '2026-09-28T18:11:41.345Z'::timestamptz, '2026-09-28T18:11:41.345Z'::timestamptz, '2026-09-28T18:11:41.345Z'::timestamptz, NULL)
  ON CONFLICT DO NOTHING
  RETURNING id
)
