UNION ALL SELECT id, 'comment', NULL, 'On phones a record now has a top toolbar from the start (‹ back, main action, labeled ⋯ menu with delete last). The header collapses into it with the scroll itself: the avatar shrinks to icon size and the name docks next to ‹, 1:1 with the finger in both directions, and settles open or docked on release. Desktop unchanged.
