WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 182, 'CI auto-fix: session waits for green CI; red CI goes back to the worker', '[NEO-132](https://linear.app/neosleep/issue/NEO-132/one-date-picker-component-strict-date-validation) was pushed with green local tests, but CI (e2e, \~15 min) failed on GitHub and nobody was told. The pre-push hook runs unit tests only; nothing watches CI after a push.

## Change (decided in form ci-autofix-2026-09, Łukasz 2026-09-28)

1. One shared rule file (`.claude/ci-autofix.json`), used by the VS Code session and the nightly worker (same rules for every worker): max 2 fix attempts per branch, fixes limited to making the failing tests pass, comment format.
2. Session: the Stop hook waits for CI on the pushed HEAD. Pending means wait, and the PR link isn''t handed over yet. Red means fix and push again (max 2), then stop and tell Łukasz.
3. Pre-push: when .vue/.css changed, run the related e2e specs locally.
4. GitHub → Linear → worker: when CI fails on a PR branch, comment the failing tests on the PR and the ticket, and move the ticket to Ready for Worker with a `ci-failed` label. The worker fixes it on the same branch (tests only), comments, and waits for CI.', NULL,
    '* A red CI blocks the session from handing over a PR link and names the failing tests
* A red CI on GitHub shows up on the PR and the Linear ticket, and the worker picks it up
* After 2 failed attempts the loop stops and asks Łukasz', 'done', 0, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/334","title":"NEO-182 CI auto-fix: green CI before the PR link, red CI goes back to a fixer"},{"kind":"artifact","url":"https://claude.ai/artifact/WRoT2Y3T3wKxnKprw3iBFf","title":"Artifact: NEO-182 CI Auto-fix"}]'::jsonb, NULL, 'linear_import', 'NEO-182', 'linear',
