SELECT id, 'created', 'done', 'Imported from Linear NEO-188', 'linear', 'import', '2026-09-28T21:33:49.900Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 189, 'Informed consent PDF: fit on 2 pages (signature alone on page 3)', '**Problem**
A signed MX informed consent (NSL-CI-DAM v1) printed 3 pages: page 3 held only the patient''s signature. The text fits on 2 pages in the compact layout, but the renderer then switched every multi-page document to the roomier layout (more air around the title), and that extra space pushed the signature to a 3rd page.

**Change**

* `fitPageLayout` keeps the roomy layout only when it does not add a page; otherwise it stays compact.
* Signature box 26 mm → 20 mm (still above the 15 mm that was unreadable in [NEO-100](https://linear.app/neosleep/issue/NEO-100/patient-consent-signature-full-screen-signing-on-phones-landscape-on)).
* Roomy-layout spacing around the title and patient banner slightly reduced.

**Done when**
The same consent with a phone signature renders on 2 pages, signature at the bottom of page 2; regression test covers "roomy never adds a page".', NULL,
    NULL, 'done', 0, ARRAY['demo-7.10']::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/340","title":"NEO-189 Informed consent PDF fits on 2 pages"},{"kind":"artifact","url":"https://claude.ai/artifact/7vPruS2dbsApNUU4P2REQx","title":"Artifact: NEO-189 Consent PDF on 2 Pages"}]'::jsonb, NULL, 'linear_import', 'NEO-189', 'linear',
    '2026-09-29T12:31:19.324Z'::timestamptz, '2026-10-03T18:23:08.523Z'::timestamptz, '2026-10-03T18:23:08.523Z'::timestamptz, '2026-10-03T18:23:08.523Z'::timestamptz)
