)
INSERT INTO platform.work_item_event (item_id, kind, to_status, body, actor, actor_kind, created_at)
SELECT id, 'created', 'done', 'Imported from Linear NEO-189', 'linear', 'import', '2026-09-29T12:31:19.324Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 190, 'Stage 0: Resend webhook + patient email send log with delivery status', 'The app shows "sent" when Resend accepts an email, even if the email later bounces or lands in spam ([NEO-162](https://linear.app/neosleep/issue/NEO-162/send-by-email-on-patient-email-not-received-doctor-chooses-which)). Nobody can see what actually happened to it.', '* New tenant table `patient_email_send`, created in a new migration. It stores the patient, the sender (user), the masked recipient, the template, the Resend message id, the status (sent|delivered|delayed|bounced|complained) and timestamps.
* `mailer.sendEmail` returns the Resend id, and `SendQuestionnaireEmailCommand` writes a row with it.
* A public `POST /api/v1/webhooks/resend` endpoint. It verifies the Svix signature (`RESEND_WEBHOOK_SECRET`, API only) and updates the status by message id.
* `GET /patient/:id/email-sends` returns the send history, protected by the territory guard.',
    '* A bounce or delivery event in Resend changes the row''s status (integration test against real Postgres).
* An unsigned or badly signed call is rejected.
* Łukasz has registered the webhook in Resend and set the secret on Cloud Run.', 'needs_review', 2, '{}'::text[],
    '[{"kind":"artifact","url":"https://claude.ai/artifact/YLzaKn7cMRhzSYT9RRQzkr","title":"Artifact: NEO-190 Email Delivery Status"}]'::jsonb, NULL, 'linear_import', 'NEO-190', 'linear',
    '2026-09-29T12:44:57.510Z'::timestamptz, '2026-09-29T12:44:57.510Z'::timestamptz, '2026-09-29T12:44:57.510Z'::timestamptz, NULL)
  ON CONFLICT DO NOTHING
  RETURNING id
)
