WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 202, '"Database error: withTenant" shown for errors that aren''t database errors', 'Łukasz (2026-09-30) keeps seeing the "Database error: withTenant" toast, most recently when sending an email to q\*\*\*@example.com. In the dev logs from the last 14 days there were 8 cases, and only 1 of them came from the database:

* 5× Resend rejected the address ([example.com](<http://example.com>) is a test domain).
* 2× a WebSocket error in Node 20 (fixed on 2026-09-25 by the move to Node 22).
* 1× the Postgres connection dropped.

`withTenant()` wraps **every** error that isn''t an AppError into `DatabaseError("withTenant")`, so a rejected email looks like a broken database.', '* `withTenant`/`withPlatform` label only real Postgres/connection errors as DB_ERROR. Other errors keep their own type and are logged with their real cause.
* The mailer turns a Resend `validation_error` into `EmailRejectedError` (422, `EMAIL_REJECTED`) with a clear message. The app shows "The mail server rejected this address — check the patient''s email".
* When the Postgres connection drops, the transaction is retried once.',
    '* A rejected address shows EMAIL_REJECTED instead of DB_ERROR (test).
* A non-database error is not labelled "Database error" (test).
* A real pg error is still DB_ERROR (test).', 'done', 2, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/348","title":"NEO-202 Only real DB errors are DB_ERROR; rejected email = EMAIL_REJECTED"},{"kind":"artifact","url":"https://claude.ai/artifact/FSjYEU4VZAcSjr144G3D9B","title":"Artifact: NEO-202 withTenant Error Labels"}]'::jsonb, NULL, 'linear_import', 'NEO-202', 'linear',
    '2026-09-29T23:47:26.985Z'::timestamptz, '2026-09-30T12:49:29.435Z'::timestamptz, '2026-09-30T12:49:29.435Z'::timestamptz, '2026-09-30T12:49:29.435Z'::timestamptz)
  ON CONFLICT DO NOTHING
  RETURNING id
)
