INSERT INTO platform.work_item_event (item_id, kind, to_status, body, actor, actor_kind, created_at)
SELECT id, 'created', 'done', 'Imported from Linear NEO-222', 'linear', 'import', '2026-10-03T20:21:32.468Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 223, 'Patients list: device ordered → QR becomes device tracking; doctor gets "+" add', '1. On the PWA patients list the Next step column always shows the QR button. Once a device has been ordered for the patient, the next step is following that order, not the patient questionnaires.
2. Doctors can''t add patients from the list: the "+" only shows for admin/manager, even though the API already lets a doctor create a patient (assigned to them automatically, [CORE-104](https://linear.app/neosleep/issue/CORE-104/doctor-sees-only-own-patients-row-level-access-policy-for-all-entities)).', '* Patient list API returns the latest device order state per patient (same rule as [NEO-217](https://linear.app/neosleep/issue/NEO-217/device-orders-on-the-shared-documentos-status-row-draft-attention)''s deviceOrderState).
* PatientNextStep: when a device order exists (not draft/cancelled), the QR is replaced by a "Seguimiento del dispositivo" (device tracking) button showing the order state, which opens the patient''s Dispositivo tab.
* PatientsView: the "+" add button also shows for role doctor.',
    '* A patient with an ordered/received device shows device tracking, not the QR, on desktop and the phone card.
* A doctor sees "+" on /patients and the new patient lands on their own list.
* Tests cover both.

## Round 2 (Łukasz, 2026-10-04)

* Tracking starts as soon as a local entry exists (draft too), not only once ordered.
* Only one active device per patient: while an order is in progress no new one can be placed (API 409 + disabled +); follow up via that order''s comments.', 'done', 0, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/388","title":"NEO-223 Patients list device tracking, one active device order, doctor can add"},{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/374","title":"NEO-223 Patients list: device tracking replaces the QR; doctor can add patients"},{"kind":"artifact","url":"https://claude.ai/artifact/1EnoHsVzqhQNhnitzYXvzs","title":"Artifact: NEO-223 Device tracking + doctor add"}]'::jsonb, NULL, 'linear_import', 'NEO-223', 'linear',
    '2026-10-03T21:32:32.914Z'::timestamptz, '2026-10-04T09:21:31.444Z'::timestamptz, '2026-10-04T09:21:31.444Z'::timestamptz, '2026-10-04T09:21:31.444Z'::timestamptz)
  ON CONFLICT DO NOTHING
  RETURNING id
)
