WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 224, 'Estudios/Tratamientos row click does nothing (wrong route param)', 'On pwa-dev, clicking a row in Estudios or Tratamientos does nothing. The list pushes the route with param `patient_id`, but `/patients/:id` needs `id`, so the navigation is rejected silently. This was broken before [NEO-222](https://linear.app/neosleep/issue/NEO-222/estudiostratamientos-lists-open-the-right-place-in-the-patient-view), which is why that change didn''t show in the app.', '* `useEntityList.navigateToDetail` takes the id from the `detailRouteParam` field of the row and always passes it as route param `id`
* Spec: a row with `patient_id` pushes `patient-detail` with `params.id` plus the query',
    '- [ ] On pwa-dev, clicking an Estudios row opens the patient on Estudios with that study open
- [ ] On pwa-dev, clicking a Tratamientos row opens the patient on Dispositivo
- [ ] Spec covers the route param', 'done', 0, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/373","title":"NEO-224 List row click passes the detail id as route param id"},{"kind":"artifact","url":"https://claude.ai/artifact/XnET91jb1ejQx6LfWeZdFB","title":"Artifact: NEO-224 List row click opens the patient"}]'::jsonb, NULL, 'linear_import', 'NEO-224', 'linear',
    '2026-10-03T21:49:11.528Z'::timestamptz, '2026-10-03T22:08:07.702Z'::timestamptz, '2026-10-03T22:08:07.702Z'::timestamptz, '2026-10-03T22:08:07.702Z'::timestamptz)
