UNION ALL SELECT id, 'comment', NULL, 'Decision (Łukasz, 2026-10-04, NEO-225 artifact D1): **yes, one test order** — send one PRUEBA DEMO order with a test STL to OA to capture their file-upload request shape. Per standing rule, show Łukasz the exact payload/files before sending. Report the capture back on the NEO-225 artifact thread (dw-neo-225-decisions) and here.', 'linear', 'import', '2026-10-04T07:52:16.312Z'::timestamptz FROM ins;
