  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 228, 'Clínico block redesign on the patient form + CPAP device/pressure (after demo 7.10)', 'The Clínico block on the new/edit patient form is plain: a bare AHI number, a CPAP switch and a one-line Expediente médico. Approved in [NEO-226](https://linear.app/neosleep/issue/NEO-226/doctors-new-patient-form-hide-territorioestado-phone-defaults-to-mx) D1 (mockup in the [NEO-226](https://linear.app/neosleep/issue/NEO-226/doctors-new-patient-form-hide-territorioestado-phone-defaults-to-mx) Artifact), to be built after the 7.10 demo.', '* AHI basal: a large number plus a live AASM severity ruler (<5 · 5–14 · 15–29 · ≥30).
* CPAP: two tiles with mono line icons, "Usa CPAP" / "Sin CPAP".
* When "Usa CPAP" is picked: device model + pressure (cm H₂O). This needs a new migration.
* Expediente médico: a multi-line field with a character counter.',
    '* The form matches the [NEO-226](https://linear.app/neosleep/issue/NEO-226/doctors-new-patient-form-hide-territorioestado-phone-defaults-to-mx) mockup, using app icons only (no emoji).
* ~~The CPAP device and pressure are saved and shown on the patient.~~ Cut on 2026-10-04: needs a migration, stays for after the 7.10 demo.
* Tests cover the severity bands and the CPAP fields'' visibility.', 'needs_review', 0, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/400","title":"NEO-228 Clinico block: AHI severity scale, CPAP icon tiles, Expediente box"},{"kind":"artifact","url":"https://claude.ai/artifact/LsPBjR8wQC8Ardicut2uK9","title":"Artifact: NEO-228 Clínico Block"}]'::jsonb, NULL, 'linear_import', 'NEO-228', 'linear',
