WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 254, 'Appointment dialog: doctor actions when patient can''t attend', 'When a patient answers "No puedo asistir" from the appointment email, the doctor''s appointment dialog stays unchanged: "Marcar como realizada" is still the primary action and "No asistió" is offered, although the patient warned in advance (would inflate no-show stats). The doctor also has no patient phone/WhatsApp at hand.', 'For `patient_response = cannot_attend` the dialog switches to a follow-up layout:

* Reprogramar becomes the primary action
* Call / WhatsApp the patient from the dialog
* Cancel with prefilled reason "Paciente no puede asistir"
* "Mantener la cita" (patient called back and will come) clears the warning
* "No asistió" and "Marcar como realizada" hidden
  Two layout options shown as mockups; Łukasz picks one before build.',
    '* Option chosen in the design Artifact
* Dialog renders the chosen layout for cannot_attend, unchanged otherwise (component test)
* Cancel stores the reason; keep clears the warning from the doctor panel action list', 'done', 0, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/479","title":"NEO-254 Guided follow-up when the patient can''t attend (NEO-254)"},{"kind":"artifact","url":"https://claude.ai/artifact/6fLZWc4HUex7vCZZwNkkpu","title":"Artifact: NEO-254 Patient can''t attend: doctor actions"}]'::jsonb, NULL, 'linear_import', 'NEO-254', 'linear',
    '2026-10-06T00:04:55.903Z'::timestamptz, '2026-10-06T01:02:15.126Z'::timestamptz, '2026-10-06T01:02:15.126Z'::timestamptz, '2026-10-06T01:02:15.126Z'::timestamptz)
  ON CONFLICT DO NOTHING
  RETURNING id
)
