SELECT id, 'created', 'done', 'Imported from Linear NEO-254', 'linear', 'import', '2026-10-06T00:04:55.903Z'::timestamptz FROM ins
UNION ALL SELECT id, 'comment', NULL, 'Decision (D1, 2026-10-06): Option B layout (guided: contact patient → Nueva fecha / Sí vendrá / Cancelar) + the patient can suggest a preferred day/time when declining; the doctor sees it in the warning. "Marcar como realizada" and "No asistió" hidden in this state.', 'linear', 'import', '2026-10-06T00:08:43.156Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 255, 'Historia clínica: patient + doctor signatures on the consent page', 'The Historia clínica consent page shows only the patient''s e-sign stamp. Łukasz: there must be 2 signatures there, the patient''s and the doctor''s. Patients who signed before [NEO-252](https://linear.app/neosleep/issue/NEO-252/historia-clinica-pdf-show-the-patients-drawn-signature-with-the-e-sign) have no stored signature image.', 'Decisions: [https://claude.ai/artifact/BFBEYSQqtxugpEjdYy8s9s](<https://claude.ai/artifact/BFBEYSQqtxugpEjdYy8s9s>)

* D1: the doctor draws a signature when printing a patient''s HC; it prints in a "Firma del médico" panel next to the patient''s, with a dated e-sign stamp; every signing is written to audit_log. The partner-agreement signature is never reused.
* D2: a backfill script that pulls signature images out of the old signed consent PDFs. It runs as a dry-run first (list + preview); it writes to prod only after Łukasz''s OK.
* Default: no image → an empty signing line.',
    '* The HC PDF shows both panels on the consent page, each with its image when one exists.
* Tests cover both panels and the empty-line fallback.
* The dry-run report has been shown to Łukasz.', 'done', 0, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/496","title":"NEO-255 Consent page prints the patient''s drawn signature, recovered from the signed PDF"},{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/475","title":"NEO-255 Historia clínica: patient + doctor signatures on the consent page"},{"kind":"artifact","url":"https://claude.ai/artifact/JDFZFS8B5hiWbbg15BLwcm","title":"Artifact: NEO-255 Historia clínica: two signatures"}]'::jsonb, NULL, 'linear_import', 'NEO-255', 'linear',
    '2026-10-06T00:34:24.474Z'::timestamptz, '2026-10-06T01:47:09.854Z'::timestamptz, '2026-10-06T01:47:09.854Z'::timestamptz, '2026-10-06T01:47:09.854Z'::timestamptz)
  ON CONFLICT DO NOTHING
  RETURNING id
)
