WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 256, 'Patient card: hide Territorio for doctors, Citas → calendar day list incl. visits', 'On the patient card (Detalles), a doctor sees "Territorio" (a rep/manager concept, always "—" for them). The "Citas" section is a custom one-line list showing appointments only, and does not include visits (events). It looks different from the calendar''s list.', '* Hide the Territorio row when the viewer has the doctor role.
* Rebuild "Citas" with the same component as the calendar day list (CalendarDayList, [CORE-161](https://linear.app/neosleep/issue/CORE-161/calendar-day-list-in-a-popover-pin-to-right-phone-month-folds-to-week)), fed with the patient''s appointments + visits/events, sorted by time. Same component on purpose: later changes apply to both.',
    '* Doctor does not see Territorio; admin/manager/rep still do.
* Citas on the patient card renders through CalendarDayList and includes visits.
* Before/after shown in an Artifact.', 'done', 0, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/477","title":"NEO-256 Patient Citas as calendar day list incl. events; no Territorio for doctors"},{"kind":"artifact","url":"https://claude.ai/artifact/HsyftnUmSFMQq7wJgcU1TC","title":"Artifact: NEO-256 Patient Citas as calendar list"}]'::jsonb, NULL, 'linear_import', 'NEO-256', 'linear',
    '2026-10-06T00:41:55.190Z'::timestamptz, '2026-10-06T01:23:14.929Z'::timestamptz, '2026-10-06T01:23:14.929Z'::timestamptz, '2026-10-06T01:23:14.929Z'::timestamptz)
