WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 258, 'Siguiente paso: when all done, offer the Historia clínica (print / email to patient)', 'Once the patient has nothing pending, the patient card''s "Siguiente paso" panel shows a disabled "Todo completado" QR button, which is a dead end. The real next step is to hand the patient the Historia clínica, printed or by email.', '* Panel end state: the disabled QR becomes "Historia clínica", which offers Print (existing historiaEndo PDF) and Send to the patient by email.
* New API path: email the rendered Historia clínica to the patient''s email on file, audited. Delivery form (attachment vs. secure link) to be decided, see the decision form.
* i18n en/pl/mx.',
    '* With all patient items done, the panel shows the Historia clínica action instead of the disabled QR (component test).
* Print opens the same PDF as Documentos → Historia clínica.
* Email goes only to the patient''s own address, writes audit_log, and is refused without an email on file (API integration test on a real DB).
* Before/after screenshot in the Artifact.', 'done', 0, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/488","title":"NEO-258 Siguiente paso: print or email the signed Historia clínica (7-day link)"},{"kind":"artifact","url":"https://claude.ai/artifact/DsBhkBkhZmV93ZTw2T8TB6","title":"Artifact: NEO-258 Historia clínica in Siguiente paso"}]'::jsonb, NULL, 'linear_import', 'NEO-258', 'linear',
    '2026-10-06T01:52:52.240Z'::timestamptz, '2026-10-06T09:00:51.903Z'::timestamptz, '2026-10-06T09:00:51.903Z'::timestamptz, '2026-10-06T09:00:51.903Z'::timestamptz)
