UNION ALL SELECT id, 'comment', NULL, 'Instead of a dead-end disabled "Todo completado", the panel first sends the doctor to the exploration still open, then offers the finished Historia clínica. The doctor signs it, and the patient gets a 7-day link to that signed copy, not a PDF attachment.
Artifact: https://claude.ai/artifact/DsBhkBkhZmV93ZTw2T8TB6
Linear: https://linear.app/neosleep/issue/NEO-258
VS Code: vscode://anthropic.claude-code/open?session=73f1bdf8-c64f-4157-ad52-b1c1371b6a72
Create PR: https://github.com/lukasz512/NeoSleep/compare/dev...worktree-neo-258-hc-next-step-print-email?quick_pull=1&title=NEO-258%20Siguiente%…', 'linear', 'import', '2026-10-06T02:14:12.930Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 259, 'Patient app: overnight snore recording (RoncoLab-style)', 'Patients and doctors have no objective, at-home measure of snoring before and after the oral appliance. Patients today use third-party apps (RoncoLab / SnoreLab) whose results never reach the patient card. This is planned as one of the first patient-facing features.', '* Native patient app (Vue wrapped in Capacitor, iOS + Android). A PWA cannot record all night: iOS Safari suspends the mic when the screen locks.
* Overnight mic recording → snore detection (start: loudness threshold; then an on-device classifier, e.g. YAMNet "snoring" class) → morning Snore Score, timeline, short playable clips.
* Factor tagging (alcohol, appliance worn, etc.) to compare nights.
* Upload night summary (not raw audio by default) to the patient card so the doctor sees before/after treatment.
* Prerequisite: patient auth / portal (currently deferred).
* Positioning: wellness snore diary, NOT apnea detection (avoids MDR/COFEPRIS SaMD scope). Legal check before launch.
* Cheaper interim option to validate demand: patient uploads a RoncoLab screenshot/result to their card.',
    '* Patient records a full night on iOS and Android with screen locked.
* Morning view shows Snore Score + timeline + clips.
* Night summary is visible on the patient card for the doctor.
* Legal/regulatory positioning signed off; consent covers audio processing.

Rough estimate: MVP 4–6 weeks; RoncoLab-level polish months.', 'backlog', 2, '{}'::text[],
    '[]'::jsonb, NULL, 'linear_import', 'NEO-259', 'linear',
    '2026-10-07T18:15:17.073Z'::timestamptz, '2026-10-07T18:15:17.073Z'::timestamptz, '2026-10-07T18:15:17.073Z'::timestamptz, NULL)
  ON CONFLICT DO NOTHING
  RETURNING id
)
