SELECT id, 'created', 'backlog', 'Imported from Linear NEO-259', 'linear', 'import', '2026-10-07T18:15:17.073Z'::timestamptz FROM ins;
WITH ins AS (
  INSERT INTO platform.work_item
    (team_key, number, title, problem, change, done_when, status, priority, labels, links, branch,
     source, linear_identifier, created_by, created_at, updated_at, status_changed_at, completed_at)
  VALUES ('NEO', 260, 'Historia clínica: guided doctor flow (Paso X de 6, Continuar, sources, candidacy)', 'The patient card shows "7 documents" while the doctor sees 3. The progress counter counts raw checklist items: 4 HC sections + printable historiaEndo + consent + 1 more. The printable HC almost never counts as done, and the doctor gets no "what''s next".
Problem list + decisions: [https://claude.ai/artifact/YWmJRn6tMsNHUxYyuzdicY](<https://claude.ai/artifact/YWmJRn6tMsNHUxYyuzdicY>)', '* D1: replace the counter with a first-visit axis "Paso X de 6" (consent → antecedentes+STOP → medidas → exploración → ATM → resumen/firma). Estudio de sueño shown as "Siguiente", outside the step count.
* D2: the HC tile gets one primary "Continuar: <next step>" button in protocol order; every section can still be opened by hand.
* D3: a source per section, on screen and in the PDF: antecedentes → consenso internacional AOS 2021, STOP-Bang → Chung et al., signos → AADSM 2022, plus "Protocolo NeoSleep (Dra. Lorena)".
* D4: a Resumen step collects the flags and suggests Indicado/Contraindicado; the doctor confirms with one tap, then "Firmar y generar PDF".
* D5: clinical field gaps (antecedentes, signos, ATM L/R) go to Dra. Lorena first. No clinical fields change here.
* Open: whether to drop the double consent (HC PDF p3) in this ticket.',
    '* The counter never shows raw item counts, and HC counts as one step.
* Continuar opens the first missing step.
* Sources are printed in the PDF.
* The doctor signature is the last step.
* Tests are green, with a real before/after.', 'building', 0, '{}'::text[],
    '[{"kind":"pr","url":"https://github.com/lukasz512/NeoSleep/pull/497","title":"NEO-260 feat: NEO-260 print picker before the HC PDF, one consent copy"},{"kind":"spec","url":"https://claude.ai/artifact/QQQaNsz8dYDMpYNS2pHLcm","title":"Plan + decisions round 2"},{"kind":"spec","url":"https://claude.ai/artifact/9FVXED4mC4Gits8L2sM4iu","title":"Artifact: NEO-260 story + plan"}]'::jsonb, NULL, 'linear_import', 'NEO-260', 'linear',
    '2026-10-07T18:23:57.607Z'::timestamptz, '2026-10-07T18:23:57.607Z'::timestamptz, '2026-10-07T18:23:57.607Z'::timestamptz, NULL)
  ON CONFLICT DO NOTHING
  RETURNING id
)
